    # Dynamically generate the __init__ method for the new subclass
    def __init__(self, **kwargs):
        # Assign all specified fields from kwargs or default to None
        for field_name in fields:
            setattr(self, field_name, kwargs.get(field_name, None))
        # Handle SRID: allow explicit SRID via kwargs or provide a default from srid_map
        self.srid = kwargs.get('srid', srid_map.get(name))

    # Optionally provide a clean string representation
    def __repr__(self):
        field_reprs = ", ".join(f"{name}={getattr(self, name)!r}" for name in fields)
        return f"{name}({field_reprs})"

    # Assemble the dictionary that will form the class namespace
    class_dict = {
        "__init__": __init__,
        "__repr__": __repr__,
        "_srid_map": srid_map,
    }

    # If a base Point class is in scope, use it; otherwise create a simple placeholder
    base_cls = Point if 'Point' in globals() else object

    # Create and return the new subclass
    return type(name, (base_cls,), class_dict)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"{func.__name__} is deprecated: {message}",
                DeprecationWarning,
                stacklevel=2,
            )
            return func(*args, **kwargs)
        return wrapper
    return decorator

