def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    result = []
    for part in parts:
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        result.append(int(num_str) if num_str else 0)
    return tuple(result)

def parse_version(s: str) -> tuple[int, ...]:
    import re
    return tuple(int(n) for n in re.findall(r'\d+', s))

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Splits the string on dots and extracts the leading integer of each
    component. Non‑numeric components are ignored. Leading and trailing
    whitespace is stripped.

    Examples:
        parse_version("1.2.3") -> (1, 2, 3)
        parse_version("  v1.2.3") -> (1, 2, 3)
        parse_version("2.0b.1") -> (2, 0, 1)
        parse_version("") -> ()
    """
    if not s:
        return ()
    parts = s.strip().split('.')
    result = []
    for part in parts:
        num = ''
        for ch in part:
            if ch.isdigit():
                num += ch
            else:
                break
        if num:
            result.append(int(num))
        # ignore component if no leading digits
    return tuple(result)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = []
    cur = ''
    for ch in s:
        if ch.isdigit():
            cur += ch
        elif cur:
            parts.append(int(cur))
            cur = ''
    if cur:
        parts.append(int(cur))
    return tuple(parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    nums = []
    cur = ''
    for ch in s:
        if ch.isdigit():
            cur += ch
        else:
            if cur:
                nums.append(int(cur))
                cur = ''
    if cur:
        nums.append(int(cur))
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                lock.acquire()
                try:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
                finally:
                    lock.release()
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

