def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        access_order = []

        def make_key(args, kwargs):
            if kwargs:
                items = tuple(sorted(kwargs.items()))
            else:
                items = ()
            if typed:
                key_args = args + tuple(type(v) for v in args)
            else:
                key_args = args
            return key_args + items

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            # Remove expired and update LRU order
            if key in cache:
                val, expire, _ = cache[key]
                if now >= expire:
                    # expired, remove
                    cache.pop(key)
                    access_order.remove(key)
                else:
                    # refresh order
                    try:
                        access_order.remove(key)
                    except ValueError:
                        pass
                    access_order.append(key)
                    return val

            if key in cache:
                # shouldn't happen because we just cleaned above
                try:
                    access_order.remove(key)
                except ValueError:
                    pass
                access_order.append(key)
                return cache[key][0]

            # Compute value
            result = func(*args, **kwargs)
            # Add to cache
            if len(cache) >= maxsize:
                # evict least recently used
                lru_key = access_order.pop(0)
                cache.pop(lru_key, None)
            expire_time = now + ttl
            cache[key] = (result, expire_time, now)
            access_order.append(key)
            return result

        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0

        def make_key(args, kwargs):
            if not typed:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
                return key
            else:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
                return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, timestamp = entry
                if now - timestamp < ttl:
                    hits += 1
                    try:
                        cache.move_to_end(key)
                    except AttributeError:
                        cache[key] = cache.pop(key)
                    return value
                else:
                    cache.pop(key, None)
            misses += 1
            value = func(*args, **kwargs)
            cache[key] = (value, now)
            try:
                cache.move_to_end(key)
            except AttributeError:
                cache[key] = cache.pop(key)
            if maxsize is not None and len(cache) > maxsize:
                cache.popitem(last=False)
            return value

        def cache_info():
            return (hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__wrapped__ = func
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorating_function(user_function):
        cache = {}
        order = []
        def wrapper(*args, **kwargs):
            now = timer()
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for k, v in sorted(kwargs.items()))
            if key in cache:
                result, expires = cache[key]
                if expires >= now:
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return result
                else:
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            result = user_function(*args, **kwargs)
            expires = now + ttl
            cache[key] = (result, expires)
            order.append(key)
            if maxsize is not None and len(cache) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result
        return wrapper
    return decorating_function

def lru_cache(maxsize=128, typed=False):
    def decorating_function(user_function):
        cache = {}
        cache_order = []
        maxsize_local = maxsize

        def make_key(args, kwargs):
            key_parts = []
            for arg in args:
                key_parts.append(arg)
                if typed:
                    key_parts.append(type(arg))
            if kwargs:
                for k in sorted(kwargs):
                    key_parts.append(k)
                    v = kwargs[k]
                    key_parts.append(v)
                    if typed:
                        key_parts.append(type(v))
            return tuple(key_parts)

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move key to the end (most recently used)
                cache_order.remove(key)
                cache_order.append(key)
                return cache[key]
            result = user_function(*args, **kwargs)
            if maxsize_local is None or maxsize_local <= 0:
                cache[key] = result
                cache_order.append(key)
            else:
                if len(cache_order) >= maxsize_local:
                    # Evict the least recently used item
                    lru_key = cache_order.pop(0)
                    del cache[lru_key]
                cache[key] = result
                cache_order.append(key)
            return result

        # expose cache_clear and cache_info if desired
        def cache_clear():
            nonlocal cache, cache_order
            cache = {}
            cache_order = []

        def cache_info():
            return f"CacheInfo(hits={0}, misses={0}, maxsize={maxsize_local}, currsize={len(cache)})"

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        # Preserve name and docstring of the original function
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        return wrapper
    return decorating_function

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys, oldest first

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key = tuple([type(a) for a in args]) + key
                if kwargs:
                    key += tuple([type(v) for v in kwargs.values()])
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move the key to the end to mark it as recently used
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return cache[key]
            else:
                result = user_function(*args, **kwargs)
                cache[key] = result
                order.append(key)
                if maxsize is not None and len(order) > maxsize:
                    oldest = order.pop(0)
                    del cache[oldest]
                return result

        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}

        def wrapper(*args, **kwargs):
            # Create a deterministic key
            if typed:
                key = (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(v) for v in args),
                    tuple(type(v) for v in kwargs.values())
                )
            else:
                key = (
                    args,
                    tuple(sorted(kwargs.items()))
                )

            if key in cache:
                result, freq = cache[key]
                cache[key] = (result, freq + 1)
                return result

            result = user_function(*args, **kwargs)

            if maxsize and len(cache) >= maxsize:
                # Find the key with the lowest frequency
                min_freq = None
                key_to_remove = None
                for k, (_, f) in cache.items():
                    if min_freq is None or f < min_freq:
                        min_freq = f
                        key_to_remove = k
                if key_to_remove is not None:
                    del cache[key_to_remove]

            cache[key] = (result, 1)
            return result

        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorating_function(user_function):
        cache = {}           # key -> (result, count)
        hits = [0]
        misses = [0]

        if maxsize <= 0:
            # No caching; just call the function
            def wrapper(*args, **kwargs):
                misses[0] += 1
                return user_function(*args, **kwargs)
            return wrapper

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple((k, type(v)) for k, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            try:
                result, count = cache[key]
                cache[key] = (result, count + 1)
                hits[0] += 1
                return result
            except KeyError:
                misses[0] += 1
                result = user_function(*args, **kwargs)
                # Evict least frequently used item if needed
                if len(cache) >= maxsize:
                    # Find key with minimal count
                    min_key = None
                    min_count = None
                    for k, (_, c) in cache.items():
                        if min_count is None or c < min_count:
                            min_count = c
                            min_key = k
                    if min_key is not None:
                        del cache[min_key]
                cache[key] = (result, 1)
                return result

        def cache_info():
            return {"hits": hits[0], "misses": misses[0], "maxsize": maxsize, "currsize": len(cache)}

        wrapper.cache_info = cache_info
        return wrapper
    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Retrieve the first key in the dictionary's iteration order
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('dictionary is empty')
    # Pop the key to get the corresponding value
    value = self.pop(first_key)
    return first_key, value

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    first_key = next(iter(self))
    first_value = self.pop(first_key)
    return (first_key, first_value)

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

