def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(args, **kwargs)
            # Try to read from cache
            if lock:
                lock.acquire()
            try:
                cached_val = cache[cache_key]
                found = True
            except (KeyError, AttributeError):
                cached_val = None
                found = False
            finally:
                if lock:
                    lock.release()
            if found:
                return cached_val
            # Compute the result
            result = func(*args, **kwargs)
            # Store in cache
            if lock:
                lock.acquire()
            try:
                cache[cache_key] = result
            finally:
                if lock:
                    lock.release()
            return result
        return wrapper
    return decorator

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    """
    Write to the specified filename the provided text buffer.
    The file is created if it does not exist. If overwrite is True, the file will be truncated before writing;
    otherwise the text is appended. The method returns the number of bytes written, or a negative value if an error occurs.
    """
    try:
        mode = 'w' if overwrite else 'a'
        with open(file_name, mode, encoding=encoding) as f:
            f.write(text_buffer)
        # Calculate the actual number of bytes that were written.
        return len(text_buffer.encode(encoding))
    except Exception:
        return -1

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

