def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if cls_name.endswith(suffix):
            return cls_name[:-len(suffix)]
    return cls_name

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    # Keep track of all unique elements in order of first appearance
    element_order = []
    seen = set()
    for ordering in orderings:
        for elem in ordering:
            if elem not in seen:
                seen.add(elem)
                element_order.append(elem)

    # Build graph: adjacency list and indegree counts
    adj = {elem: [] for elem in element_order}
    indegree = {elem: 0 for elem in element_order}

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            if v not in adj[u]:
                adj[u].append(v)
                indegree[v] += 1

    # Kahn's algorithm for topological sorting
    from collections import deque
    zero_in = deque([node for node in element_order if indegree[node] == 0])
    result = []

    while zero_in:
        node = zero_in.popleft()
        result.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                zero_in.append(nxt)

    # If the result does not contain all elements, there was a cycle.
    # In that case, just return the order as it was built.
    if len(result) != len(element_order):
        # Fall back to the original order without fully resolving
        return element_order

    return result

def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object.

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.__provides__
    except AttributeError:
        # If the object does not declare any interfaces, return an empty declaration
        return ()

