def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for c in classes:
        redundant = False
        for other in classes:
            if other is c:
                continue
            try:
                if issubclass(c, other):
                    redundant = True
                    break
            except TypeError:
                # non‑class objects are ignored in the subclass check
                pass
        if not redundant:
            minimal.append(c)
    seen = set()
    result = []
    for cls in minimal:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = []
    cls = self.__class__
    for name, attr in vars(cls).items():
        # Skip private/internal attributes unless all=True
        if not all and name.startswith("_"):
            continue
        doc = None
        # Handle properties
        if isinstance(attr, property):
            fget = getattr(attr, "fget", None)
            doc = fget.__doc__ if fget else None
        # Handle staticmethods and classmethods
        elif isinstance(attr, (staticmethod, classmethod)):
            func = getattr(attr, "__func__", None)
            doc = func.__doc__ if func else None
        # Handle regular functions/methods
        elif callable(attr):
            doc = getattr(attr, "__doc__", None)
        # Fallback to attribute docstring
        else:
            doc = getattr(attr, "__doc__", None)
        if doc:
            results.append((name, str(doc).strip()))
    return results

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls = self.__class__

    def _collect(c):
        names = []
        ann = getattr(c, "__annotations__", {})
        names.extend(ann.keys())
        for k, v in c.__dict__.items():
            if k.startswith("_"):
                continue
            if callable(v):
                continue
            names.append(k)
        return names

    if all:
        seen = set()
        unique = []
        for c in reversed(cls.__mro__):
            if c is object:
                continue
            for name in _collect(c):
                if name not in seen:
                    seen.add(name)
                    unique.append(name)
        return unique
    else:
        names = _collect(cls)
        seen = set()
        unique = []
        for name in names:
            if name not in seen:
                seen.add(name)
                unique.append(name)
        return unique

def names(self, all=False): # pylint:disable=redefined-builtin
