    # Collect attribute names from class (and base classes)
    attr_names = {}
    for cls in self.__class__.__mro__:
        for name, obj in cls.__dict__.items():
            if not name.startswith('_') and not callable(obj):
                attr_names[name] = None
    # If requested, also include instance attributes
