def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, (list, tuple)):
            # Recursively expand nested sequences
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    for arg in sequence:
        # Treat strings and non-iterables as atomic interfaces.
        if isinstance(arg, (str, bytes)):
            output.append(arg)
            continue

        # If the element is iterable but not a string, we need to decide whether to expand it.
        if isinstance(arg, (list, tuple, set)):
            # Heuristic: if it looks like an implements spec (e.g. ('implements', iface)),
            # keep it unchanged.  Otherwise, flatten it.
            if len(arg) == 2 and isinstance(arg[0], str) and arg[0].lower() == 'implements':
                output.append(arg)
            else:
                # Recursively expand nested iterable.
                _normalizeargs(arg, output)
        else:
            output.append(arg)

    return output

