    return False

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    # Determine if C optimizations are required, via an environment variable
    required = False
    try:
        env = __import__('os').environ
        required = env.get('C_OPTIMIZATIONS_REQUIRED', '').lower() in ('1', 'true', 'yes')
    except Exception:
        # Environment access unavailable; assume not required
        pass

    # Attempt to import the C-optimized module
    try:
        return __import__('c_optimizations')
    except Exception:
        if required:
            raise ImportError('C optimizations required but not available')
        return False

