        if initial_value is not None:
            # Reinitialize existing bins with the initial value
            try:
                bin_count = len(self.bins)
            except AttributeError:
                # If bins were never created, create an empty list first
                self.bins = []
                bin_count = 0
            self.bins = [initial_value] * bin_count
