def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Try a direct attribute storing the indices
    attr_name = f"_err_{coord_name}_indices"
    if hasattr(self, attr_name):
        return getattr(self, attr_name)

    # Fall back to a dict that maps coordinate names to indices
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        return self._err_indices.get(coord_name, [])

    # As a last resort, look for the error array and infer indices
    err_attr = f"_err_{coord_name}"
    if hasattr(self, err_attr):
        err = getattr(self, err_attr)
        try:
            return [i for i, v in enumerate(err) if v is not None]
        except TypeError:
            # err is not iterable
            pass

    raise AttributeError(f"Cannot find error indices for coordinate '{coord_name}'")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve the error array for the given coordinate name
    err_arr = None
    # Try common attribute names that might store error arrays
    for attr in ("_errors", "_errs", "_err", "errs", "errors", "err"):
        if hasattr(self, attr):
            attr_dict = getattr(self, attr)
            if isinstance(attr_dict, dict) and coord_name in attr_dict:
                err_arr = attr_dict[coord_name]
            break

    if err_arr is None:
        # No error information found for the coordinate
        return np.array([], dtype=int)

    # Convert to a NumPy array; preserve dtype if possible
    err_arr = np.asarray(err_arr)

    # Create a mask that ignores invalid (nan, inf, None) values
    masked = np.ma.masked_invalid(err_arr)

    # Return the flat indices where error values are valid
    return np.flatnonzero(~masked.mask)

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.
    """
    # Ensure the context has the expected attributes.
    if not hasattr(context, "error"):
        context.error = {}
    if not hasattr(context, "value"):
        context.value = {}

    # Map coordinate names to short labels used for errors.
    coord_map = {}
    if hasattr(self, "coordinates"):
        for i, coord in enumerate(self.coordinates[:3]):
            coord_map[coord] = ["x", "y", "z"][i]

    # Existing context.value subcontexts remain untouched; we only
    # add error information for fields that start with "error_".
    for idx, field in enumerate(self.fields):
        if not field.startswith("error_"):
            continue

        # Remove the 'error_' prefix.
        err_part = field[len("error_") :]

        # Split the remaining part into the coordinate part and the suffix
        # (if any).  For example "E_low" -> ("E", "_low").
        if "_" in err_part:
            coord_part, suffix = err_part.split("_", 1)
            suffix = "_" + suffix
        else:
            coord_part = err_part
            suffix = ""

        # Translate the coordinate part into the short form (x, y, z) if it
        # appears as one of the first three coordinate fields.
        short_name = coord_map.get(coord_part, coord_part)

        # Store the index of the error field in the context error dictionary.
        context.error[short_name + suffix] = {"index": idx}

