    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, lvl):
        result = {}
        for k, v1 in a.items():
            if k not in b:
                # key is absent in b – include it
                result[k] = v1
            else:
                v2 = b[k]
                # both values are dictionaries and we can recurse
                if isinstance(v1, dict) and isinstance(v2, dict):
                    # determine next recursion level
                    next_lvl = lvl - 1 if lvl > 0 else lvl
                    sub = _diff(v1, v2, next_lvl)
                    if sub:
                        result[k] = sub
                else:
                    # primitives or differing types – include if values differ
                    if v1 != v2:
                        result[k] = v1
        return result

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Handle one- or multi-dimensional indices
    try:
        # If a tuple, treat as multi-dimensional index
        if isinstance(coord, tuple):
            # Check that the tuple has the right dimensionality
            if len(coord) != self.dim:
                return
            # Verify each component is within the valid range
            for ix, bin_count in zip(coord, self.bins):
                if ix < 0 or ix >= bin_count:
                    return
            # All indices are valid – increment the bin
            self.hist[coord] += weight
        else:
            # Assume a single index for 1D histograms
            if coord < 0 or coord >= self.bins:
                return
            self.hist[coord] += weight
    except Exception:
        # In case histogram data are somehow incompatible, silently fail
        return

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not KUBE_LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex "
                          f"'{KUBE_LABEL_KEY_REGEX.pattern}'"}
                )

        # Validate value(s)
        def _validate_val(v):
            if isinstance(v, list):
                for sv in v:
                    _validate_val(sv)
            else:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    if not KUBE_LABEL_VALUE_REGEX.match(v):
                        errors.append(
                            {v: f"Label value '{v}' does not match the regex "
                                f"'{KUBE_LABEL_VALUE_REGEX.pattern}'"}
                        )

        _validate_val(value)

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
