    key_pattern = r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$'
    val_pattern = r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$'
    key_regex = re.compile(key_pattern)
    val_regex = re.compile(val_pattern)

    errors = []

    if not isinstance(labels, dict):
