                )

        # Validate value type and regex
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            val_str = value if isinstance(value, str) else value.decode()
            if not val_regex.match(val_str):
                errors.append(
                    {
                        val_str: f"Label value '{val_str}' does not match the regex \"{val_pattern}\""
                    }
                )

    if errors:
