def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Recursively generate a default observer_schema from a Kubernetes resource manifest.
    Non-dict/non-list values are replaced with None.
    When first_level is True, the identifying fields ('metadata.name' and 'metadata.namespace')
    are preserved from the original manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries; only top level has first_level True
            nested = generate_default_observer_schema_dict(value, False)
            result[key] = nested
        elif isinstance(value, list):
            # Delegate list handling to the corresponding helper
            result[key] = generate_default_observer_schema_list(value)
        else:
            result[key] = None

    if first_level:
        # Preserve identifying metadata fields
        meta = manifest_dict.get("metadata", {})
        if isinstance(result.get("metadata"), dict):
            preserved = {}
            for field in ("name", "namespace"):
                if field in meta:
                    preserved[field] = meta[field]
            # Only keep the preserved fields; drop all others
            result["metadata"] = preserved
        else:
            # If metadata wasn't a dict, recreate it with preserved fields
            preserved = {}
            for field in ("name", "namespace"):
                if field in meta:
                    preserved[field] = meta[field]
            if preserved:
                result["metadata"] = preserved
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a part of a Kubernetes resource.

    Parameters
    ----------
    manifest_dict : dict
        Partial Kubernetes resource dictionary.
    first_level : bool, optional
        Indicates that the dictionary represents the whole observer_schema of a Kubernetes
        resource. Defaults to False.

    Returns
    -------
    dict
        Generated partial observer_schema dictionary.
    """
    def _process(subdict, is_first_level):
        result = {}
        for key, value in subdict.items():
            if isinstance(value, dict):
                # If this is the top level, preserve certain identifying fields as is.
                if is_first_level and key in ("apiVersion", "kind"):
                    result[key] = value
                elif is_first_level and key == "metadata":
                    # Keep the whole metadata dict unchanged
                    result[key] = value
                else:
                    result[key] = _process(value, False)
            elif isinstance(value, list):
                # Maintain list structure, apply processing to each element.
                processed_list = []
                for element in value:
                    if isinstance(element, dict):
                        processed_list.append(_process(element, False))
                    else:
                        processed_list.append(None)
                result[key] = processed_list
            else:  # scalar value
                if is_first_level and key in ("apiVersion", "kind"):
                    # Preserve apiVersion and kind values
                    result[key] = value
                else:
                    # Replace non-dict/list values with None
                    result[key] = None
        return result

    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")
    return _process(manifest_dict, first_level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes
    resource definition.

    For non-dict and non-list values, replace them with None. If ``first_level`` is
    True, copy the identifying fields ('apiVersion', 'kind', and 'metadata')
    directly from the original manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve list structure, replacing dict elements recursively
            # and non-dict items with None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Non-list, non-dict value
            if first_level and key in ("apiVersion", "kind", "metadata"):
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Update a nested ``last_applied_manifest`` dictionary with values from a Kubernetes
    API response based on the provided ``observer_schema``.

    Parameters
    ----------
    last_applied_manifest : dict
        The ``last_applied_manifest`` being updated. Keys that are not present
        will be added from ``response``.
    observer_schema : dict
        Schema describing the fields to observe. For each key, the value is
        either ``None`` for a scalar field, or a nested dictionary representing
        a sub‑schema for an object field.
    response : dict
        Partial response from the Kubernetes API.

    Raises
    ------
    KeyError
        If an observed field is missing from ``response``.
    """
    for key, sub_schema in observer_schema.items():
        # The response must contain the observed key
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")

        # If the key is not present in last_applied_manifest, initialise it
        if key not in last_applied_manifest or last_applied_manifest[key] is None:
            if sub_schema is None:
                # Scalar value: copy directly
                last_applied_manifest[key] = response[key]
            else:
                # Nested object: ensure sub‑dict exists
                sub_resp = response[key]
                if not isinstance(sub_resp, dict):
                    # If the API returned something other than a dict, just store it
                    last_applied_manifest[key] = sub_resp
                else:
                    # Initialise nested dict if missing and recurse
                    if key not in last_applied_manifest or not isinstance(
                        last_applied_manifest[key], dict
                    ):
                        last_applied_manifest[key] = {}
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], sub_schema, sub_resp
                    )
        else:
            # The key exists; if it is a nested object and has a sub‑schema, recurse
            if sub_schema is not None and isinstance(last_applied_manifest[key], dict) and isinstance(response[key], dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        list[dict]: A list of default observer schema dictionaries for each resource
            that lacks a custom observer schema.
    """
    # Collect names of resources that already have an observer schema.
    existing_schemas = getattr(app.spec, "observer_schemas", [])
    existing_names = {
        # Some applications might store the resource reference as a dict under "resource"
        # or simply provide the "name" directly.  Try both to stay robust.
        obs.get("resource", {}).get("name") if isinstance(obs, dict) else None for obs in existing_schemas
    } | {obs.get("name") for obs in existing_schemas if isinstance(obs, dict)}

    # Prepare a list of default schemas
    default_schemas = []

    for resource in getattr(app.spec, "manifest", []):
        # Guard against missing metadata
        metadata = getattr(resource, "metadata", None)
        if metadata is None:
            continue
        res_name = getattr(metadata, "name", None) or (metadata.get("name") if isinstance(metadata, dict) else None)
        if not res_name:
            continue

        # Skip if the resource already has an observer schema
        if res_name in existing_names:
            continue

        # Build a very generic default observer schema.  The actual structure will
        # depend on the concrete ObserverSchema implementation, but a minimal example
        # is provided here for illustration purposes.
        default_schema = {
            "resource": {
                "kind": getattr(resource, "kind", None) or (resource.get("kind") if isinstance(resource, dict) else None),
                "name": res_name,
                "apiVersion": getattr(resource, "apiVersion", None) or (resource.get("apiVersion") if isinstance(resource, dict) else None),
            },
            "metadata": {
                # Use the application name and resource name to form a unique identifier
                "name": f"{app.name}.{res_name}.observer" if hasattr(app, "name") else f"observer.{res_name}"
            }
        }
        default_schemas.append(default_schema)

    return default_schemas

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    The generated schemas are stored in ``app.spec.default_observer_schema`` and
    also returned for convenience.
    """
    # Ensure the application has a spec with a manifest attribute
    manifest = getattr(app, "spec", None) and getattr(app.spec, "manifest", None)
    if not manifest:
        # No manifest to process
        return {}

    default_schemas = {}
    for resource in manifest:
        # Skip if the resource already specifies a custom observer schema
        if resource is None or isinstance(resource, (list, tuple)):
            continue
        custom_schema = resource.get("observer_schema")
        if custom_schema is not None:
            continue

        # Extract useful fields for the key and default schema
        api_version = resource.get("apiVersion") or ""
        kind = resource.get("kind") or ""
        meta = resource.get("metadata", {})
        name = meta.get("name") or ""
        namespace = meta.get("namespace")

        # Skip resources without a name (cannot construct a unique key)
        if not name:
            continue

        key = f"{api_version}/{kind}/{name}"
        default_schemas[key] = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {
                "name": name,
                "namespace": namespace,
            },
            "status": {},
        }

    # Attach the generated schemas back to the application spec if possible
    if hasattr(app.spec, "default_observer_schema"):
        app.spec.default_observer_schema.update(default_schemas)
    else:
        setattr(app.spec, "default_observer_schema", default_schemas)

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Prepare containers for the resulting default schemas
    default_schemas = {}

    # If the application spec or manifest is missing, return an empty mapping
    spec = getattr(app, "spec", None)
    if spec is None:
        return default_schemas

    manifest = getattr(spec, "manifest", [])
    if not isinstance(manifest, list):
        return default_schemas

    # The user might already have defined custom schemas.  Store them for quick lookup.
    # The exact key format is inferred from the application design – we assume the
    # custom_schemas map keys in the form "<kind>::<namespace>::<name>".
    custom_schemas = getattr(spec, "observer_schemas", {})
    if not isinstance(custom_schemas, dict):
        custom_schemas = {}

    for entry in manifest:
        # Skip non-dict entries or missing data
        if not isinstance(entry, dict):
            continue

        kind = entry.get("kind")
        metadata = entry.get("metadata", {})
        if not isinstance(metadata, dict):
            metadata = {}
        name = metadata.get("name")
        namespace = metadata.get("namespace", "default")

        # Skip if mandatory fields are missing
        if not kind or not name:
            continue

        key = f"{kind}::{namespace}::{name}"
        if key in custom_schemas:
            # Skip resources that already have a custom observer schema
            continue

        # Build a simple default schema entry.  This can be expanded later if
        # more sophisticated defaults are required.
        default_schemas[key] = {
            "kind": kind,
            "namespace": namespace,
            "name": name,
        }

    return default_schemas

