        inv_type = inventory.get("type")
        # If the inventory has a recognised type, use it as the spec version
        if inv_type and inv_type in getattr(self, "schemas", {}):
            self.spec_version = inv_type

    # Fetch the schema for the current spec version
    schema = getattr(self, "schemas", {}).get(self.spec_version)
    if schema is None:
        raise ValueError(f"Unsupported or missing spec version: {self.spec_version}")

    # Basic required field checks
    required = schema.get("required", [])
    for field in required:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")

    # Property type checks
    properties = schema.get("properties", {})
    for field, rules in properties.items():
        if field in inventory:
            expected = rules.get("type")
            if expected:
                value = inventory[field]
                if expected == "string" and not isinstance(value, str):
                    raise ValueError(f"Field '{field}' expected to be string")
                if expected == "integer" and not isinstance(value, int):
                    raise ValueError(f"Field '{field}' expected to be integer")
                if expected == "boolean" and not isinstance(value, bool):
                    raise ValueError(f"Field '{field}' expected to be boolean")
                if expected == "object" and not isinstance(value, dict):
                    raise ValueError(f"Field '{field}' expected to be object")
                # Add other type checks if needed

    # If all checks pass, store validated inventory
    self.inventory = inventory
    return True

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if extract_spec_version:
            typ = inventory.get('type')
            if typ in getattr(self, 'allowed_spec_versions', ()):
                self.spec_version = typ
        if not getattr(self, 'spec_version', None):
            raise ValueError('spec_version is not set')
        errors = []
        if not isinstance(inventory, dict):
            errors.append('Inventory must be a dict.')
        else:
            if 'name' not in inventory:
                errors.append('Missing required key "name".')
            if 'items' in inventory and not isinstance(inventory['items'], list):
                errors.append('"items" must be a list.')
        if errors:
            raise ValueError('Invalid inventory: ' + '; '.join(errors))
        return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure we have a dictionary to validate
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dict")

    # Optionally adjust the spec version based on the inventory type
    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str):
            # If the class has a mapping of type to spec version, use it
            spec_map = getattr(self, "_SPEC_VERSION_MAP", {})
            if inv_type in spec_map:
                self.spec_version = spec_map[inv_type]

    # Basic sanity checks that an inventory should contain
    required_top_keys = {"name", "type", "items"}
    missing_keys = required_top_keys - inventory.keys()
    if missing_keys:
        raise ValueError(f"Missing required inventory keys: {', '.join(sorted(missing_keys))}")

    # Validate each item in the inventory
    for idx, item in enumerate(inventory.get("items", []), start=1):
        if not isinstance(item, dict):
            raise ValueError(f"Inventory item {idx} is not a dict")
        # Example minimal checks: items must have an 'id' and a 'value'
        if "id" not in item:
            raise ValueError(f"Inventory item {idx} missing required 'id' field")
        if "value" not in item:
            raise ValueError(f"Inventory item {idx} missing required 'value' field")

    # If we reach this point, the inventory passes our checks
    return True

def validate(self, inventory, extract_spec_version=False):
        """
        Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        def semver_ge(v1, v2):
            # Compare two semantic version strings “major.minor.patch”
            def parse(v):
                return tuple(int(x) for x in v.split('.') if x.isdigit())
            return parse(v1) >= parse(v2)

        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        # Determine spec version
        spec_ver = self.spec_version
        if extract_spec_version:
            inv_type = inventory.get("type")
            type_to_ver = {
                "global": "1.0.0",
                "host": "2.0.0",
                "profile": "3.0.0",
            }
            spec_ver = type_to_ver.get(inv_type, spec_ver)

        # Store determined version back to the instance for further checks
        self.spec_version = spec_ver

        # Required keys for all inventories
        required_keys = ["id", "type", "services"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' in inventory")

        # Services must be a list
        if not isinstance(inventory.get("services"), list):
            raise ValueError("'services' must be a list")

        # Additional checks depending on specification version
        if semver_ge(spec_ver, "2.0.0"):
            # Inventories of spec_version >= 2.0 must contain a 'policy' key
            if "policy" not in inventory:
                raise ValueError("Inventory of spec_version >= 2.0 must contain a 'policy' key")

        # If all checks pass, return True
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalize manifest digests into a set
        present_digests = set()
        for mf in manifest_files:
            if hasattr(mf, 'digest'):
                dig = mf.digest
            elif isinstance(mf, dict) and 'digest' in mf:
                dig = mf['digest']
            else:
                raise ValueError("Manifest entry must have a 'digest' attribute or key")
            present_digests.add(dig)

        # Normalize used digests into a set
        used_digests = set(digests_used)

        # Digests expected to be present but missing in the manifest
        missing = used_digests - present_digests
        if missing:
            raise ValueError(f"Missing digests in manifest: {sorted(missing)}")

        # Digests present in the manifest but unused
        unused = present_digests - used_digests
        if unused:
            raise ValueError(f"Unused digests present in manifest: {sorted(unused)}")
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Extract the set of digests that are actually recorded in the manifest.
    if isinstance(manifest_files, dict):
        # Assume a mapping from file names to digest strings.
        manifest_digests = set(manifest_files.values())
    else:
        # Assume an iterable (list, tuple, set) of digest strings.
        manifest_digests = set(manifest_files)

    missing = digests_used - manifest_digests
    if missing:
        raise ValueError(
            f"Missing digests required but not present in manifest: {sorted(missing)}"
        )

    unused = manifest_digests - digests_used
    if unused:
        raise ValueError(
            f"Digests present in manifest but not used anywhere: {sorted(unused)}"
        )

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected 'prior' to be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # The objects are assumed internally consistent, so we only need to
    # validate that prior represents an older version of the inventory.

    # 1. Check that both objects expose a version attribute.
    if not hasattr(self, "inventory_version") or not hasattr(prior, "inventory_version"):
        raise AttributeError(
            "Both inventory objects must have an 'inventory_version' attribute"
        )
    self_ver = getattr(self, "inventory_version")
    prior_ver = getattr(prior, "inventory_version")

    # 2. Ensure the types of the versions are comparable (prefer ints or floats)
    if not isinstance(self_ver, (int, float)) or not isinstance(prior_ver, (int, float)):
        raise TypeError("'inventory_version' must be an int or float")

    # 3. Validate that prior is indeed older (strictly less)
    if prior_ver >= self_ver:
        raise ValueError(
            f"'prior.inventory_version' ({prior_ver}) must be less than "
            f"current 'inventory_version' ({self_ver})"
        )

    # 4. (Optional) Compare timestamps if available
    if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        self_ts = getattr(self, "timestamp")
        prior_ts = getattr(prior, "timestamp")

        # Support datetime or numeric timestamps but avoid importing datetime
        if isinstance(self_ts, (int, float)) and isinstance(prior_ts, (int, float)):
            if prior_ts >= self_ts:
                raise ValueError(
                    f"'prior.timestamp' ({prior_ts}) must be earlier than "
                    f"current 'timestamp' ({self_ts})"
                )
        elif isinstance(self_ts, object) and isinstance(prior_ts, object):
            # If they are datetime-like, attempt comparison
            try:
                if prior_ts >= self_ts:
                    raise ValueError(
                        f"'prior.timestamp' ({prior_ts}) must be earlier than "
                        f"current 'timestamp' ({self_ts})"
                    )
            except Exception:
                # If comparison fails, ignore silently
                pass

    # 5. Ensure inventory types match
    inventory_type_self = getattr(self, "inventory_type", None)
    inventory_type_prior = getattr(prior, "inventory_type", None)
    if inventory_type_self is not None and inventory_type_prior is not None:
        if inventory_type_self != inventory_type_prior:
            raise ValueError(
                f"Inventory type mismatch: {inventory_type_self} != {inventory_type_prior}"
            )

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Verify that the prior argument is of the same type as self
        if type(prior) is not type(self):
            raise TypeError(f"prior must be an instance of {type(self).__name__}")
        # Ensure that both inventories refer to the same repository, if the
        # ``repository`` attribute is defined on either side.
        repo_self = getattr(self.inventory, "repository", None)
        repo_prior = getattr(prior.inventory, "repository", None)
        if repo_self is not None and repo_prior is not None:
            if repo_self != repo_prior:
                raise ValueError(
                    "prior inventory repository does not match the current inventory"
                )
        # Retrieve the inventory identifiers.  The common attribute names are
        # ``id`` and ``inventory_id``; use whichever is available and raise
        # an informative error if neither can be found.
        try:
            id_self = self.inventory.id
        except AttributeError:
            try:
                id_self = self.inventory.inventory_id
            except AttributeError:
                raise AttributeError(
                    "current inventory does not expose an 'id' or 'inventory_id' attribute"
                )
        try:
            id_prior = prior.inventory.id
        except AttributeError:
            try:
                id_prior = prior.inventory.inventory_id
            except AttributeError:
                raise AttributeError(
                    "prior inventory does not expose an 'id' or 'inventory_id' attribute"
                )
        # The prior identifier must represent an earlier version.  We assume that
        # the identifiers are either integers or strings that can be compared
        # lexicographically to represent version precedence.
        try:
            if id_prior >= id_self:
                raise ValueError(
                    f"prior inventory id {id_prior} must be less than current inventory id {id_self}"
                )
        except TypeError:
            # If the types are not directly comparable, try to coerce to a common
            # format (e.g., integer or string) before comparing.
            try:
                # First try integer comparison
                id_prior_int = int(id_prior)
                id_self_int = int(id_self)
                if id_prior_int >= id_self_int:
                    raise ValueError(
                        f"prior inventory id {id_prior_int} is not less than current inventory id {id_self_int}"
                    )
            except Exception:
                # Fall back to string comparison
                if str(id_prior) >= str(id_self):
                    raise ValueError(
                        f"prior inventory id {id_prior} is not less than current inventory id {id_self}"
                    )
        # All sanity checks passed; the prior inventory is considered a valid
        # predecessor of the current inventory.
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # basic type sanity check
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")
    # required attributes
    required = ["inventory_version", "inventory_name", "inventory_date"]
    for attr in required:
        if not hasattr(self, attr):
            raise AttributeError(f"Current inventory missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior inventory missing required attribute '{attr}'")
    # version must be strictly less
    if prior.inventory_version >= self.inventory_version:
        return False
    # name must match (identifies the same logical inventory)
    if prior.inventory_name != self.inventory_name:
        return False
    # date must be earlier
    if prior.inventory_date >= self.inventory_date:
        return False
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    # Determine how the inventory is structured. It may be a mapping from version
    # to data or a list of records containing versions.
    data = None

    # If inventory is a mapping from version to something
    if isinstance(inventory, dict):
        data = inventory.get(version)
    # If inventory itself is a list of records with a 'version' key
    if data is None and isinstance(inventory, list):
        data = [rec for rec in inventory if rec.get('version') == version]
    # If still None, nothing found – return empty dict
    if data is None:
        return result

    # Helper: add a content file to a logical path in the result
    def add_to_result(lp, cf):
        if lp not in result:
            result[lp] = set()
        result[lp].add(cf)

    # Now interpret the data structure
    if isinstance(data, dict):
        # Expect mapping from logical_path -> list/set/tuple of content files
        for lp, files in data.items():
            if isinstance(files, (list, set, tuple)):
                result[lp] = set(files)
            else:
                result[lp] = {files}
    elif isinstance(data, list):
        # Iterate over records
        for entry in data:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                lp, cf = entry[0], entry[1]
                add_to_result(lp, cf)
            elif isinstance(entry, dict):
                lp = entry.get('logical_path')
                cf = entry.get('content_file')
                if lp is not None and cf is not None:
                    add_to_result(lp, cf)
    # If data is a single record (tuple or dict)
    elif isinstance(data, (list, tuple)) and len(data) >= 2:
        add_to_result(data[0], data[1])
    elif isinstance(data, dict) and 'logical_path' in data and 'content_file' in data:
        add_to_result(data['logical_path'], data['content_file'])

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    mapping = {}

    def _add_data(data):
        for logical_path, files in data.items():
            if logical_path not in mapping:
                mapping[logical_path] = set()
            if isinstance(files, (set, list, tuple)):
                mapping[logical_path].update(files)
            else:
                mapping[logical_path].add(files)

    # If inventory is a plain dict keyed by versions
    if isinstance(inventory, dict):
        # Add data for the requested version
        if version in inventory:
            _add_data(inventory[version])
        # Include data from later versions as duplicates
        later_versions = [v for v in inventory if isinstance(v, (int, float)) and v > version]
        for lv in sorted(later_versions):
            _add_data(inventory[lv])

    # If inventory has a 'by_version' attribute (e.g., custom object)
    elif hasattr(inventory, 'by_version') and isinstance(inventory.by_version, dict):
        if version in inventory.by_version:
            _add_data(inventory.by_version[version])
        later_versions = [v for v in inventory.by_version if isinstance(v, (int, float)) and v > version]
        for lv in sorted(later_versions):
            _add_data(inventory.by_version[lv])

    # If inventory has a callable to retrieve version data
    elif hasattr(inventory, 'get_version'):
        try:
            data = inventory.get_version(version)
            _add_data(data)
        except Exception:
            pass
        # Attempt to include later versions if the inventory exposes them
        if hasattr(inventory, 'available_versions'):
            for lv in sorted(v for v in inventory.available_versions if v > version):
                try:
                    _add_data(inventory.get_version(lv))
                except Exception:
                    pass

    return mapping

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def to_set(item):
        if isinstance(item, (set, frozenset)):
            return set(item)
        if isinstance(item, (list, tuple)):
            return set(item)
        return {item}

    # Determine where the version data lives in the inventory
    version_map_container = inventory.get('versions', inventory) if isinstance(inventory, dict) else {}
    if not isinstance(version_map_container, dict):
        return {}

    # Map for the requested version
    target_mapping = version_map_container.get(version, {})
    result = {}

    for logical_path, content in target_mapping.items():
        result[logical_path] = to_set(content)

    # Add duplicate references from later versions
    for later_ver, later_mapping in version_map_container.items():
        try:
            # Try to compare strings or numbers in a safe way
            is_later = later_ver > version
        except Exception:
            # fall back if comparison fails
            try:
                is_later = float(later_ver) > float(version)
            except Exception:
                is_later = True
        if is_later and isinstance(later_mapping, dict):
            for logical_path, content in later_mapping.items():
                if logical_path in result:
                    result[logical_path].update(to_set(content))

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Build a sorted list of all versions in the inventory.  We assume the
    # keys of the inventory are comparable (e.g. integers, strings that
    # sort in version order, or objects that support the ``<`` operator).
    try:
        all_versions = sorted(inventory.keys())
    except TypeError:
        # If the keys cannot be sorted (perhaps they are dictionaries or
        # custom objects), fall back to the order provided by ``inventory``.
        all_versions = list(inventory.keys())
    # Find the starting index for the requested version.
    start_index = None
    for i, ver in enumerate(all_versions):
        if ver == version:
            start_index = i
            break
    if start_index is None:
        # The requested version is not present; return an empty mapping.
        return {}
    # Iterate over the requested version and all later versions.
    result = {}
    for ver in all_versions[start_index:]:
        mapping = inventory.get(ver, {})
        # ``mapping`` is expected to be a dict where keys are logical paths
        # and values are iterables of content files (e.g., sets or lists).
        if not isinstance(mapping, dict):
            # If we encounter a non-dict, skip it.
            continue
        for logical_path, content_files in mapping.items():
            # Ensure we have a set for the logical path in the result.
            if logical_path not in result:
                result[logical_path] = set()
            # If the value is not iterable, treat it as a single item.
            if isinstance(content_files, (list, tuple, set)):
                result[logical_path].update(content_files)
            else:
                result[logical_path].add(content_files)
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    errors = getattr(self, "errors", None)
    if errors is None:
        errors = []
        self.errors = errors

    if not fixity:
        errors.append("Missing or empty fixity block.")
        return

    # Determine the structure of the fixity block
    if isinstance(fixity, dict):
        # Expect a mapping of path -> checksum or dict containing checksum info
        items = list(fixity.items())
    elif isinstance(fixity, list):
        # Expect a list of records that each contain a 'path' key
        items = []
        for record in fixity:
            if not isinstance(record, dict):
                errors.append(f"Fixity record {record} is not a dictionary.")
                continue
            path = record.get("path")
            if not path:
                errors.append(f"Fixity record {record} missing 'path' key.")
                continue
            items.append((path, record))
    else:
        errors.append(f"Fixity block is of unsupported type {type(fixity).__name__}.")
        return

    # Validate each entry
    for path, record in items:
        # Standardise path representation
        norm_path = path.strip().lstrip("./")
        if norm_path not in manifest_files:
            errors.append(f"File '{norm_path}' referenced in the fixity block but not present in the manifest.")
            continue

        # Check that a checksum/hash is provided
        if isinstance(record, dict):
            if not any(key in record for key in ("hash", "checksum")):
                errors.append(f"Missing checksum for file '{norm_path}' in the fixity block.")
        elif isinstance(record, str):
            # Accept a bare checksum string if the dict case is not used
            pass
        else:
            errors.append(f"Unsupported record type for file '{norm_path}': {type(record).__name__}.")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and make sure that only files
        listed in the manifest are referenced.
        """
        # Ensure arguments are of expected types
        if not isinstance(manifest_files, (list, tuple, set)):
            raise ValueError("`manifest_files` must be a list, tuple, or set of file names")
        if not isinstance(fixity, dict):
            raise ValueError("`fixity` must be a mapping of file paths to checksum info")

        allowed_algos = {"md5", "sha1", "sha256", "sha512"}

        # Validate each entry in the fixity block
        for path, info in fixity.items():
            # Only files present in the manifest should be referenced
            if path not in manifest_files:
                raise ValueError(f"Fixity references unknown file: {path}")

            # Each info value must be a dict containing required keys
            if not isinstance(info, dict):
                raise ValueError(f"Fixity info for '{path}' must be a dictionary")

            if "checksum" not in info:
                raise ValueError(f"Missing 'checksum' for file '{path}'")
            checksum = info["checksum"]
            if not isinstance(checksum, str) or not checksum:
                raise ValueError(f"Checksum for '{path}' must be a non‑empty string")

            if "algorithm" not in info:
                raise ValueError(f"Missing 'algorithm' for file '{path}'")
            algorithm = str(info["algorithm"]).lower()
            if algorithm not in allowed_algos:
                raise ValueError(
                    f"Unsupported checksum algorithm '{algorithm}' for file '{path}'"
                )

            # Optional size field – if present it must be an integer
            if "size" in info and not isinstance(info["size"], int):
                raise ValueError(
                    f"Size for '{path}' must be an integer, got {type(info['size']).__name__}"
                )

def validate_fixity(self, fixity, manifest_files):
