        """Validate fixity block in inventory.

        Check that the fixity block is a dictionary whose keys are file
        paths appearing in ``manifest_files`` and whose values are strings
        (hashes). Raises ``ValueError`` if the structure is wrong or if any
        referenced file is not listed in the manifest.
        """
        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")
        for file_path, hash_value in fixity.items():
            if not isinstance(file_path, str):
                raise ValueError(f"Fixity key must be a string, got {type(file_path).__name__} for key {file_path!r}")
            if not isinstance(hash_value, str):
                raise ValueError(f"Fixity value must be a string, got {type(hash_value).__name__} for key {file_path!r}")
            if file_path not in manifest_files:
                raise ValueError(f"Fixity references unknown file: {file_path!r}")
        return True

