def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data = {}
    # List all entries in the specified folder
    try:
        entries = os.listdir(folder)
    except OSError:
        return data

    # Prepare a mapping from basename to all entries sharing that basename
    base_to_entries = {}
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if os.path.isfile(full_path):
            base, ext = os.path.splitext(entry)
            base_to_entries.setdefault(base, []).append(full_path)

    # For each basename that has an XML file, collect its data
    for base, paths in base_to_entries.items():
        xml_path = None
        others = []
        for p in paths:
            if p.lower().endswith('.xml'):
                xml_path = p
            else:
                others.append(p)

        if xml_path is not None:
            try:
                with open(xml_path, 'r', encoding='utf-8') as fp:
                    xml_content = fp.read()
            except Exception:
                xml_content = None
            data[base] = {
                'xml': xml_content,
                'files': others
            }
    return data

