def _explore_zipfile(zip_path):
    import zipfile
    import os
    mapping = {}
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for info in zf.infolist():
            # Skip directories
            if info.is_dir():
                continue
            fname = info.filename
            base = os.path.splitext(os.path.basename(fname))[0]
            mapping.setdefault(base, []).append(fname)
    # Keep only entries where an XML file exists for the base
    result = {k: v for k, v in mapping.items() if any(f.lower().endswith('.xml') for f in v)}
    return result

