def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        def _format(o, level):
            prefix = ' ' * level
            if hasattr(o, 'pretty') and o is not self:
                # Avoid infinite recursion for self-referential objects
                return o.pretty(indent=level, debug=debug)
            if isinstance(o, dict):
                lines = []
                for k, v in sorted(o.items()):
                    lines.append(f"{prefix}{k}:")
                    lines.append(_format(v, level + 2))
                return "\n".join(lines)
            if isinstance(o, (list, tuple, set)):
                lines = []
                for item in o:
                    lines.append(_format(item, level + 2))
                return "\n".join(lines)
            return prefix + repr(o)

        representation = _format(self, indent)
        if debug:
            return f"{self.__class__.__name__} at {hex(id(self))}:\n" + representation
        return representation

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        def _format(obj, ind):
            if isinstance(obj, (list, tuple, set)):
                items = []
                for el in obj:
                    items.append(_format(el, ind + 4))
                opening, closing = ('[', ']') if isinstance(obj, list) else ('(', ')') if isinstance(obj, tuple) else ('{', '}')
                return f"{opening}\n" + ",\n".join(items) + f"\n{' ' * ind}{closing}"
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    items.append(f"{_format(k, ind + 4)}: {_format(v, ind + 4)}")
                return f"{{\n" + ",\n".join(items) + f"\n{' ' * ind}}}"
            if hasattr(obj, "pretty") and callable(obj.pretty):
                return obj.pretty(indent=ind, debug=debug)
            # For other types, use repr
            return repr(obj)

        spacer = " " * indent
        cls_name = self.__class__.__name__
        if hasattr(self, "__dict__"):
            attrs = []
            for key, value in self.__dict__.items():
                val_str = _format(value, indent + 4)
                extra = f"  # {type(value).__name__}" if debug else ""
                attrs.append(f"{key} = {val_str}{extra}")
            body = ",\n".join(attrs)
            return f"{cls_name}(\n{spacer}    {body}\n{spacer})"
        else:
            # fallback to simple repr
            return repr(self)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    def _format(obj, cur_indent):
        pref = ' ' * cur_indent
        if isinstance(obj, dict):
            lines = []
            for key, value in obj.items():
                lines.append(f"{pref}{key}:")
                lines.append(_format(value, cur_indent + 4))
            return "\n".join(lines)
        if isinstance(obj, (list, tuple, set)):
            lines = []
            for item in obj:
                lines.append(f"{pref}-")
                lines.append(_format(item, cur_indent + 4))
            return "\n".join(lines)
        if hasattr(obj, "__dict__"):
            lines = []
            for key, value in obj.__dict__.items():
                lines.append(f"{pref}{key}:")
                lines.append(_format(value, cur_indent + 4))
            return "\n".join(lines)
        if debug:
            return f"{pref}{repr(obj)} ({type(obj).__name__})"
        else:
            return f"{pref}{repr(obj)}"

    return _format(self, indent)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    base_indent = ' ' * indent
    if hasattr(self, "__dict__"):
        items = []
        for key, value in sorted(self.__dict__.items()):
            if hasattr(value, "pretty") and callable(value.pretty):
                val_str = value.pretty(indent + 4, debug=debug)
            else:
                val_str = f"{value!r}"
            items.append(f"{' ' * (indent + 4)}{key}: {val_str}")
        if items:
            inner = "\n".join(items)
            rep = f"{base_indent}{self.__class__.__name__}(\n{inner}\n{base_indent})"
        else:
            rep = f"{base_indent}{self.__class__.__name__}()"
    else:
        rep = f"{base_indent}{repr(self)}"
    if debug:
        rep += f" [id={id(self)}]"
    return rep

def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        spacer = ' ' * indent
        header = f"{spacer}{self.__class__.__name__}"
        if debug:
            header += f" (id={id(self)})"
        header += ":"
        lines = [header]

        # Iterate through instance attributes
        for name, value in vars(self).items():
            # For collections, iterate further
            if isinstance(value, (list, tuple)):
                lines.append(f"{spacer}  {name}:")
                for idx, item in enumerate(value):
                    prefix = f"{spacer}    [{idx}]:"
                    if hasattr(item, "pretty"):
                        lines.append(item.pretty(indent + 4, debug))
                    else:
                        lines.append(f"{prefix} {repr(item)}")
            # For objects with their own pretty method, recurse
            elif hasattr(value, "pretty") and callable(value.pretty):
                lines.append(f"{spacer}  {name}:")
                lines.append(value.pretty(indent + 4, debug))
            else:
                # Simple scalar value
                lines.append(f"{spacer}  {name}: {repr(value)}")

        return "\n".join(lines)

