def tzname_in_python2(namefunc):
    """Wrap a tzname callback to return a bytestring in Python 2."""
    def wrapper(*args, **kwargs):
        res = namefunc(*args, **kwargs)
        try:
            # In Python 2, unicode is the unicode type; str is bytes
            if isinstance(res, unicode):
                # Encode to bytes, use default encoding or ignore errors
                res = res.encode(errors='ignore')
        except NameError:
            # Python 3 – unicode type not defined, skip conversion
            pass
        return res
    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    import sys
    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3 and not isinstance(name, str):
            # In Python 2, convert unicode to byte string
            return name.encode('utf-8')
        return name
    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    # Determine the unicode type for this interpreter
    try:
        unicode_type = unicode  # Python 2
    except NameError:
        unicode_type = str     # Python 3

    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if result is None:
            return None

        # In Python 2, ensure the result is a byte string
        if isinstance(result, unicode_type):
            try:
                import sys
                # Use the default encoding for Python 2
                return result.encode(sys.getdefaultencoding())
            except Exception:
                # Fallback: just return the result if encoding fails
                return result

        # In Python 3, or if the result is already a bytes object, return it unchanged
        return result

    return wrapper

