            version = _version
        except Exception:
            # If we can't import either module, return default
            return default

    if pkg_name:
        try:
            ver = version(pkg_name)
            return {"version": ver, "full-revisionid": ver}
        except PackageNotFoundError:
            return default
        except Exception:
            return default
    # If we couldn't determine a package name, fall back to default
