def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : iterable
        The individual parts of a version (e.g., major, minor, patch, prerelease).
    style : str or callable
        Determines how the pieces are combined.
        * If a callable is supplied, it will be called with the pieces as
          positional arguments and its return value used.
        * For string styles the following shortcuts are recognised:
          - ``"dot"``  : pieces joined with a dot (``.``)
          - ``"dash"`` : pieces joined with a hyphen (``-``)
          - ``"full"`` or ``"default"`` : prefixed with ``v`` and joined with a dot
        * If the string contains ``{}`` placeholders, it is treated as a format
          string and ``style.format(*pieces)`` is applied.
        * If a string does not match any of the above, the pieces are simply
          joined with a dot as a fallback.

    Returns
    -------
    str
        The formatted version string.
    """
    # If a callable is provided, use it directly.
    if callable(style):
        return style(*pieces)

    # Ensure pieces are strings for formatting.
    parts = [str(p) for p in pieces]

    if isinstance(style, str):
        # Normalised style key lookup
        key = style.lower()
        if key == "dot":
            return ".".join(parts)
        if key == "dash":
            return "-".join(parts)
        if key in ("full", "default"):
            return "v" + ".".join(parts)

        # Try a format string.
        try:
            return style.format(*parts)
        except Exception:
            # Fall back to default join behaviour below.
            pass

    # Default behaviour: join with a dot.
    return ".".join(parts)

