def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    if args is not None:
        if isinstance(args, str):
            cmd.append(args)
        else:
            cmd.extend(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    # Determine where to send stderr
    import subprocess
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Execute the command
    result = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        text=True
    )

    if verbose:
        if result.stdout:
            print(result.stdout, end='')
        if result.stderr:
            import sys
            print(result.stderr, end='', file=sys.stderr)

    return result

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    The function can be used as a decorator factory::

        @register_vcs_handler('git')
        def handler(...):
            ...

    After registration, the handler can be accessed via::

        register_vcs_handler.handlers['git']

    Returns:
        The original method unmodified.
    """
    if method is None:
        def decorator(func):
            if not hasattr(register_vcs_handler, "handlers"):
                register_vcs_handler.handlers = {}
            register_vcs_handler.handlers[vcs] = func
            return func
        return decorator
    else:
        if not hasattr(register_vcs_handler, "handlers"):
            register_vcs_handler.handlers = {}
        register_vcs_handler.handlers[vcs] = method
        return method

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    if method is not None and callable(method):
        # Direct registration (no decorator syntax)
        method._vcs_handler = vcs
        global _vcs_registry
        try:
            _vcs_registry = globals().get('_vcs_registry', {})
        except Exception:
            _vcs_registry = {}
        _vcs_registry[vcs] = method
        return method

    def decorator(func):
        # Decorator usage: @register_vcs_handler('git')
        func._vcs_handler = vcs
