        try:
            _vcs_registry = globals().get('_vcs_registry', {})
        except Exception:
            _vcs_registry = {}
        _vcs_registry[vcs] = func
        return func

    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine iterable collection of objects in the hierarchy.
    objects = getattr(self, 'objects', None)
    if objects is None:
        objects = getattr(self, 'children', None)
    if objects is None:
        # If the object itself is iterable, use it directly.
        if hasattr(self, '__iter__'):
            objects = self
        else:
            # No objects found; nothing to validate.
            return 0, 0

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested.
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    is_valid = obj.validate()
                else:
                    # Default to True if no validate method is available.
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation failed for object {obj}: {exc}")

        # Check the digest of the object if requested.
        if is_valid and check_digests:
            try:
                if hasattr(obj, 'check_digest'):
                    obj.check_digest()
                # If the method doesn't exist, we assume it is fine.
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check failed for object {obj}: {exc}")

        if is_valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f"Warning: object {obj} is invalid.")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import os
        import hashlib
        import logging

        if not hasattr(self, "storage_root"):
            raise AttributeError("The object must have a 'storage_root' attribute pointing to the root directory to validate.")

        num_objects = 0
        good_objects = 0

        for root, dirs, files in os.walk(self.storage_root):
            for fn in files:
                num_objects += 1
                file_path = os.path.join(root, fn)

                # Optional object validation
                if validate_objects:
                    try:
                        with open(file_path, "rb") as f:
                            data = f.read()
                            if not data:
                                if show_warnings:
                                    logging.warning(f"Empty file detected during validation: {file_path}")
                            else:
                                good_objects += 1
                    except Exception as exc:
                        if show_warnings:
                            logging.warning(f"Could not read file during validation: {file_path} ({exc})")
                else:
                    good_objects += 1

                # Optional digest checking
                if check_digests:
                    try:
                        sha256 = hashlib.sha256()
                        with open(file_path, "rb") as f:
                            for chunk in iter(lambda: f.read(8192), b""):
                                sha256.update(chunk)
                        _digest = sha256.hexdigest()
                        # The digest is calculated for the sake of validation; it can be logged or stored as needed.
                    except Exception as exc:
                        if show_warnings:
                            logging.warning(f"Could not compute checksum for file: {file_path} ({exc})")

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Initialize counters
    num_objects = 0
    good_objects = 0

    # Determine the collection of objects to validate.
    # It is assumed that the owning class provides a list/iterator named
    # `storage_objects` or `root_objects`.  If neither is present, nothing
    # is validated.
    objects = getattr(self, 'storage_objects', None)
    if objects is None:
        objects = getattr(self, 'root_objects', [])
    # If objects is still None, default to an empty list to avoid iteration errors.
    if objects is None:
        objects = []

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object via a `validate()` method if requested.
        if validate_objects:
            try:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Validation failed for {obj}: {exc}")

        # Perform digest check via a `check_digest()` method if requested.
        if check_digests:
            try:
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    obj.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Digest check failed for {obj}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    root = self.root_path
    for dirpath, dirnames, filenames in os.walk(root):
        for fname in filenames:
            num_objects += 1
            full_path = os.path.join(dirpath, fname)
            if validate_objects and not os.path.isfile(full_path):
                if show_warnings:
                    print(f"Missing file: {full_path}")
                continue
            if check_digests:
                try:
                    with open(full_path, 'rb') as f:
                        data = f.read()
                    digest = hashlib.sha256(data).hexdigest()
                    rel_path = os.path.relpath(full_path, root)
                    expected = getattr(self, 'digests', {}).get(rel_path)
                    if expected is None:
                        if show_warnings:
                            print(f"No digest for {rel_path}")
                        continue
                    if digest != expected:
                        if show_warnings:
                            print(f"Digest mismatch for {rel_path}: expected {expected}, got {digest}")
                        continue
                except Exception as e:
                    if show_warnings:
                        print(f"Error processing {full_path}: {e}")
                    continue
            good_objects += 1
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return "1"
    parts = version.split('.')
    last = parts[-1]
    if not last.isdigit():
        # if the last part isn't purely numeric, just append .1
        return version + ".1"
    width = len(last)
    new_num = int(last) + 1
    if last.startswith('0'):
        parts[-1] = str(new_num).zfill(width)
    else:
        parts[-1] = str(new_num)
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os, json

    # Load the root inventory which is expected to live in the current working directory.
    root_inventory_path = os.path.join(os.getcwd(), "root_inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory file not found: {root_inventory_path}")

    with open(root_inventory_path, "r", encoding="utf-8") as f:
        root_inventory = json.load(f)

    # This will hold any digest mismatches found between a version's inventory
    # and the root inventory.  Format:
    # { filename: [ {version: ..., root_digest: ..., current_digest: ...}, ... ] }
    differing_digests = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in {ver_dir}")

        with open(inv_path, "r", encoding="utf-8") as f:
            inv = json.load(f)

        # Ensure the inventory for this version contains all files that appear
        # in the root inventory up to this point.
        for filename, root_digest in root_inventory.items():
            if filename not in inv:
                raise AssertionError(
                    f"File '{filename}' missing from inventory in {ver_dir}"
                )
            current_digest = inv[filename]
            if current_digest != root_digest:
                differing_digests.setdefault(filename, []).append(
                    {
                        "version": ver_dir,
                        "root_digest": root_digest,
                        "current_digest": current_digest,
                    }
                )

    # Store the differences on the instance for later validation checks.
    self.differing_digests = differing_digests
    return differing_digests

def validate_version_inventories(self, version_dirs):
    """Validate that each version directory contains an inventory,
    and record any digest mismatches with the root inventory.
    Returns a tuple (errors, mismatched_files) where
    - errors: list of error messages (missing inventories, etc.)
    - mismatched_files: dict mapping file path to a dict of root and version digests
    """
    import os, json

    errors = []
    mismatched_files = {}

    # Determine root inventory path: assume self.root_inventory_path exists; fallback to 'inventory.json' in base dir
    root_inventory_path = getattr(self, "root_inventory_path", os.path.join(self.base_path, "inventory.json"))

    # Load root inventory
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except Exception as e:
        errors.append(f"Failed to load root inventory at '{root_inventory_path}': {e}")
        root_inventory = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(self.base_path, version_dir, "inventory.json")
        if not os.path.isfile(inventory_path):
            errors.append(f"Missing inventory file in version directory '{version_dir}'")
            continue

        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                version_inventory = json.load(f)
        except Exception as e:
            errors.append(f"Failed to load inventory at '{inventory_path}': {e}")
            continue

        # Compare digests
        for path, root_digest in root_inventory.items():
            ver_digest = version_inventory.get(path)
            if ver_digest is None:
                # File missing in this version inventory
                errors.append(f"File '{path}' missing from inventory in '{version_dir}'")
                continue
            if ver_digest != root_digest:
                mismatched_files.setdefault(path, {})[version_dir] = {
                    "root_digest": root_digest,
                    "version_digest": ver_digest,
                }

    # Store mismatched info for later use if needed
    self.mismatched_files = mismatched_files
    return errors, mismatched_files

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"not exists: {path}"

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f"not a file or directory: {path}"

    # Directory: search for a "0=*" namaste file
    namaste_path = None
    try:
        for entry in os.scandir(path):
            if entry.is_file() and entry.name.startswith('0='):
                namaste_path = entry.path
                break
    except Exception as e:
        return f"error accessing directory {path}: {e}"

    if not namaste_path:
        return f"no namaste file found in directory: {path}"

    try:
        with open(namaste_path, 'r', encoding='utf-8') as f:
            content = f.read().strip()
    except Exception as e:
        return f"error reading namaste file {namaste_path}: {e}"

    # Simple heuristics based on content
    lower = content.lower()
    if 'root' in lower:
        return 'root'
    if 'object' in lower:
        return 'object'
    if 'inventory' in lower:
        return 'file'

    return f"unknown namaste content in {namaste_path}: {content[:30]}..."

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params to include the given bug IDs."""
    if bug_ids is None:
        return params

    # Ensure bug_ids is an iterable of integers or strings that can be cast to int
    try:
        bug_ids_list = list(bug_ids)
    except TypeError:  # bug_ids is a single value
        bug_ids_list = [bug_ids]

    # Normalise existing ids in params (if any)
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = [int(x) for x in existing.split(',') if x]
        else:
            existing_ids = list(existing)
        all_ids = set(existing_ids) | set(bug_ids_list)
    else:
        all_ids = set(bug_ids_list)

    if all_ids:
        # Store as a comma‑separated string, sorted for consistency
        params['ids'] = ','.join(map(str, sorted(all_ids)))
    else:
        # Remove ids key if there are no ids left
        params.pop('ids', None)

    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # No bug IDs to amend; return params unchanged
    if not bug_ids:
        return params
    # Add bug ids to the params. Bugzilla typically expects a comma-separated
    # string under the key "ids" for multiple bugs, or "id" for a single bug.
    if isinstance(bug_ids, (list, tuple)):
        # Filter out any None values
        cleaned = [str(bid) for bid in bug_ids if bid is not None]
        if cleaned:
            params["ids"] = ",".join(cleaned)
    else:
        params["id"] = str(bug_ids)
    return params

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params: merge any existing `ids` value
        with the provided `bug_ids`. Returns the updated params dict.
        """
        if params is None:
            params = {}
        if not isinstance(params, dict):
            raise ValueError("params must be a dict")

        if not bug_ids:
            return params

        # Normalize bug_ids to a set of strings
        if isinstance(bug_ids, (list, tuple)):
            new_ids = set(map(str, bug_ids))
        else:
            new_ids = {str(bug_ids)}

        # Merge with any existing ids in params
        if 'ids' in params:
            existing = params['ids']
            if isinstance(existing, str):
                existing_ids = set(existing.split(','))
            else:
                existing_ids = set(map(str, existing))
            merged_ids = sorted(existing_ids | new_ids)
            # Preserve original type: string if it was string
            if isinstance(existing, str):
                params['ids'] = ','.join(merged_ids)
            else:
                params['ids'] = merged_ids
        else:
            # Preserve original type: list if bug_ids is list/tuple, else list
            if isinstance(bug_ids, (list, tuple)):
                params['ids'] = list(new_ids)
            else:
                params['ids'] = list(new_ids)

        return params

def deep_merge_nodes(nodes):
    """
    Deep merge a list of YAML nodes, where each node is a tuple
    (ScalarNode key, MappingNode|any value). Duplicate keys are
    merged recursively if the values are MappingNodes; otherwise
    the value from the later node wins.

    The function assumes that `ruamel.yaml.nodes.ScalarNode` and
    `ruamel.yaml.nodes.MappingNode` are available in the
    runtime environment.
    """
    from ruamel.yaml.nodes import MappingNode

    def merge_mapping_nodes(m1, m2):
        """Merge two MappingNodes and return a new MappingNode."""
        merged_items = deep_merge_items(m1.value + m2.value)
        return MappingNode(tag=m1.tag, value=merged_items)

    def deep_merge_values(v1, v2):
        """Merge two values when a conflict occurs."""
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            return merge_mapping_nodes(v1, v2)
        # For non-mapping values, the later value overwrites the earlier one.
        return v2

    def deep_merge_items(items):
        """Process a list of (key_node, value_node) tuples."""
        result = []
        key_index = {}

        for key_node, value_node in items:
            key = key_node.value
            if key not in key_index:
                key_index[key] = len(result)
                result.append((key_node, value_node))
            else:
                idx = key_index[key]
                existing_key, existing_value = result[idx]
                merged_value = deep_merge_values(existing_value, value_node)
                result[idx] = (existing_key, merged_value)
        return result

    return deep_merge_items(list(nodes))

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
