    """Replace any custom string URL items with values in args."""
    import re

    # Replace {key} placeholders
    def _brace_repl(m):
        key = m.group(1)
        return str(url_args.get(key, m.group(0)))

    url = re.sub(r'\{([^}]+)\}', _brace_repl, url)

    # Replace :key placeholders (common in some URL patterns)
    def _colon_repl(m):
        key = m.group(1)
        return str(url_args.get(key, m.group(0)))

    url = re.sub(r':([^/]+)', _colon_repl, url)
    return url

