    """
    def recursive_replace(obj):
        if isinstance(obj, dict):
            keys_to_replace = []
            for key, val in list(obj.items()):
                if key == register_value:
                    # Store value temporarily to reassign
                    keys_to_replace.append((key, val))
                else:
                    recursive_replace(val)
            for key, val in keys_to_replace:
                obj[register_number] = val
                del obj[key]
        elif isinstance(obj, list):
            for item in obj:
                recursive_replace(item)
        # For all other types (int, str, etc.) no action needed
    recursive_replace(flow_params)
    return flow_params

