def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine which style to use
    if platform == 'this':
        posix = not os.name == 'nt'   # True on POSIX (non‑Windows)
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError(f"Unsupported platform: {platform!r}")

    # Regular expression for matching arguments
    if posix:
        # Matches either quoted strings (single or double) or unquoted tokens
        token_re = re.compile(r'''(?:(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|[^\s]+)''')
    else:
        # Windows: quoted strings or non-whitespace tokens
        token_re = re.compile(r'''(?:(?:"(?:\\.|[^"\\])*")|\S+)''')

    raw_tokens = token_re.findall(s)

    def _unquote(token, posix):
        if not token:
            return token
        if posix:
            # Strip surrounding quotes if any
            if token[0] in ("'", '"') and token[-1] == token[0]:
                token = token[1:-1]
            # Unescape backslashes before any character
            return re.sub(r'\\(.)', r'\1', token)
        else:
            # Windows CMD rules
            # Strip surrounding quotes if any
            if token and token[0] == '"' and token[-1] == '"':
                token = token[1:-1]
                # Process backslashes before quotes
                out = []
                i = 0
                while i < len(token):
                    if token[i] == '\\':
                        # Count consecutive backslashes
                        bs = 0
                        while i < len(token) and token[i] == '\\':
                            bs += 1
                            i += 1
                        if i < len(token) and token[i] == '"':
                            # Each pair of backslashes results in one backslash
                            out.append('\\' * (bs // 2))
                            if bs % 2:
                                # Odd backslash escapes the quote
                                out.append('"')
                                i += 1
                            else:
                                # Just a quote
                                out.append('"')
                                i += 1
                        else:
                            # Backslashes not preceding a quote are literal
                            out.append('\\' * bs)
                    else:
                        out.append(token[i])
                        i += 1
                token = ''.join(out)
            return token

    return [_unquote(tok, posix) for tok in raw_tokens]

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    # Determine actual platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    # POSIX regex: matches quoted (single or double) or unquoted tokens
    if platform == 1:
        pattern = r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|([^\s'"]+))'''
        tokens = []
        for m in re.finditer(pattern, s):
            quoted = m.group(1) if m.group(1) is not None else m.group(2)
            if quoted is not None:
                # Unescape backslashes and surrounding quotes
                tokens.append(re.sub(r'\\(.)', r'\1', quoted))
            else:
                tokens.append(m.group(3))
        return tokens
    # Windows CMD regex: matches quoted (double) or unquoted tokens
    if platform == 0:
        pattern = r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|([^\s"]+))'''
        tokens = []
        for m in re.finditer(pattern, s):
            quoted = m.group(1)
            if quoted is not None:
                # In CMD, escape only double quotes and backslashes before double quotes
                # This simplified unescapes typical cases
                unescaped = re.sub(r'\\(.)', r'\1', quoted)
                tokens.append(unescaped)
            else:
                tokens.append(m.group(2))
        return tokens
    # Fallback: simple split on whitespace
    return s.split()

