    # Git Bash sets the environment variable MSYSTEM
    if os.getenv("MSYSTEM"):
        return True

    # Some installations may expose a path containing 'git-bash'
    path = os.getenv("PATH", "")
    if path:
        # Normalize path segments for case-insensitive comparison on Windows
        for segment in path.split(os.pathsep):
            if "git-bash" in segment.lower():
                return True

    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    if os.name != 'nt':
        return False
    msys_env = os.environ.get('MSYSTEM', '').lower()
    if msys_env.startswith('mingw') or msys_env.startswith('msys') or msys_env.startswith('cygwin'):
        return True
    return os.environ.get('OSTYPE', '').startswith('msys')

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Accept matcher as a string "VAR:DEFAULT" or simply "VAR",
    # or a sequence where first element is the variable name and the optional second element is the default.
    if isinstance(matcher, str):
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    elif isinstance(matcher, (tuple, list)):
        if not matcher:
            raise TypeError("Matcher tuple/list cannot be empty")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError("Matcher must be a string or a tuple/list")

    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default is not None:
            value = default
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value.strip() if isinstance(value, str) else value

