    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract the variable name and optional default from the matcher.
    try:
        # Try attribute access first
        name = matcher.name
    except AttributeError:
        try:
            # Try dictionary key access
            name = matcher['name']
        except (TypeError, KeyError):
            # Fallback to sequence indexing
            try:
                name = matcher[0]
            except Exception:
                raise ValueError("Matcher must provide a 'name' of the environment variable.")
    # Determine the default value if provided
    default = None
    if hasattr(matcher, 'default'):
        default = matcher.default
    elif isinstance(matcher, dict):
        default = matcher.get('default')
    elif isinstance(matcher, (list, tuple)) and len(matcher) > 1:
        default = matcher[1]
    # Resolve the environment variable
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    # No variable set and no default – raise an error
    raise KeyError(f"Environment variable '{name}' is not set and no default provided.")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name and optional default
    name = None
    default = None

    # Handle matcher as a dictionary
    if isinstance(matcher, dict):
        # Common keys that might contain the variable name
        for key in ('name', 'key', 'var', 'variable'):
            if key in matcher:
                name = matcher[key]
                break
        # Get the default if provided
        for dkey in ('default', 'fallback', 'value'):
            if dkey in matcher:
                default = matcher[dkey]
                break

    # Handle matcher as a tuple or list (name, default?)  
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) == 2:
            default = matcher[1]

    # Handle matcher as a string; try "VAR" or "VAR:default"
    elif isinstance(matcher, str):
        parts = matcher.split(':', 1)
        name = parts[0]
        if len(parts) == 2:
            default = parts[1]

    # If we still don't have a name, raise an error
    if not name:
        raise ValueError("Matcher does not contain a variable name")

    # Fetch the environment variable
    value = os.getenv(name, default)

    # If no value found and no default provided, raise an error
    if value is None:
        raise KeyError(f"Environment variable '{name}' is not set and no default value was provided")

    return value

