def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Dump the object to a YAML string using the optional custom Dumper.
    yaml_output = yaml.safe_dump(
        obj,
        default_flow_style=False,
        allow_unicode=True,
        Dumper=dumper,
    )
    # On Python 2, yaml.safe_dump returns a byte string; convert it to unicode.
    if isinstance(yaml_output, bytes):
        try:
            return yaml_output.decode("utf-8")
        except Exception:
            return yaml_output.decode("latin-1")
    # On Python 3, the output is already a str (unicode).
    return yaml_output

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string."""
    if dumper is None:
        dumper = yaml.safe_dump
    # Dump the object with pretty formatting and unicode support
    dumped = dumper(obj, default_flow_style=False, allow_unicode=True)
    # In Py2, yaml.safe_dump returns a byte string in some cases.
    # Ensure the result is a unicode string for Py2 and a str (Unicode) for Py3.
    try:
        import sys
        if sys.version_info[0] < 3 and isinstance(dumped, str):
            return dumped.decode('utf-8')
    except Exception:
        pass
    return dumped

