def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, configparser, logging, os, re
    try:
        import yaml
        _yaml_available = True
    except ImportError:
        _yaml_available = False

    config_results = {}
    error_records = []
    logger_name = __name__
    for filename in config_filenames:
        config_data = None
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                ext = os.path.splitext(filename)[1].lower()
                if ext == '.json':
                    config_data = json.load(f)
                elif ext in ('.yaml', '.yml'):
                    if not _yaml_available:
                        raise RuntimeError('PyYAML is required for YAML files')
                    config_data = yaml.safe_load(f)
                elif ext in ('.ini', '.cfg'):
                    parser = configparser.ConfigParser()
                    parser.read_file(f)
                    config_data = {s: dict(parser.items(s)) for s in parser.sections()}
                else:
                    raise RuntimeError(f'Unsupported file extension: {ext}')
            if config_data is None:
                config_data = {}
        except Exception as exc:
            # Build a LogRecord for the error
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading configuration file {filename}: {exc}',
                args=(),
                exc_info=exc
            )
            error_records.append(record)
            config_results[filename] = None
            continue

        # Resolve environment variables in string values
        def _replace_env(val):
            if isinstance(val, str):
                return os.path.expandvars(val)
            elif isinstance(val, dict):
                return {k: _replace_env(v) for k, v in val.items()}
            elif isinstance(val, list):
                return [_replace_env(v) for v in val]
            else:
                return val

        if resolve_env:
            try:
                config_data = _replace_env(config_data)
            except Exception as exc:
                record = logging.LogRecord(
                    name=logger_name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error resolving environment variables in {filename}: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)

        # Apply overrides (top‑level merge)
        if overrides and isinstance(overrides, dict):
            try:
                config_data.update(overrides)
            except Exception as exc:
                record = logging.LogRecord(
                    name=logger_name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error applying overrides to {filename}: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)

        config_results[filename] = config_data

    return (config_results, error_records)

import json, os, logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]
    configs = {}
    log_records = []

    logger = logging.getLogger(__name__)
    class ListHandler(logging.Handler):
        def emit(self, record):
            log_records.append(record)
    list_handler = ListHandler()
    logger.setLevel(logging.DEBUG)
    logger.addHandler(list_handler)

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                content = f.read()
                if resolve_env:
                    content = os.path.expandvars(content)
                data = json.loads(content)
                if overrides and isinstance(data, dict):
                    data.update(overrides)
                configs[fname] = data
        except FileNotFoundError:
            logger.error(f"Configuration file not found: {fname}")
        except json.JSONDecodeError as e:
            logger.error(f"JSON decode error in file {fname}: {e}")
        except Exception as e:
            logger.error(f"Unexpected error loading {fname}: {e}")

    logger.removeHandler(list_handler)
    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, os
    logger = logging.getLogger('config_loader')
    configurations = {}
    error_records = []
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                config_data = json.load(f)
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading {filename}: {e}',
                args=None,
                exc_info=None
            )
            error_records.append(record)
            continue
        if overrides:
            if isinstance(config_data, dict):
                config_data.update(overrides)
        if resolve_env:
            def resolve(value):
                if isinstance(value, str):
                    while '${' in value and '}' in value:
                        start = value.find('${')
                        end = value.find('}', start)
                        if start == -1 or end == -1:
                            break
                        var = value[start+2:end]
                        val = os.getenv(var, '')
                        value = value[:start] + val + value[end+1:]
                    return value
                elif isinstance(value, dict):
                    return {k: resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [resolve(v) for v in value]
                else:
                    return value
            config_data = resolve(config_data)
        configurations[filename] = config_data
    return configurations, error_records

