def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    "protocol_version must be a tuple or None, got %r" %
                    (protocol_version,)
                )
            return (
                {protocol_version: cls.PROTOCOL_HANDLERS[protocol_version]}
                if protocol_version in cls.PROTOCOL_HANDLERS
                else {}
            )
        # Return a copy so callers cannot modify the internal registry
        return dict(cls.PROTOCOL_HANDLERS)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle None explicitly
    if seq is None:
        return None, None

    # If seq is already a sequence type, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # If seq is an iterable (but not a string/bytes), convert it to a tuple
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        # For generators or other iterables
        try:
            return tuple(seq), type(seq)
        except Exception:
            # Fallback: wrap in a list
            return [seq], type(seq)

    # For scalar values, wrap them into a one‑element tuple
    return (seq,), type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence as _Seq
    # If seq is already a sequence type, return it unchanged
    if isinstance(seq, _Seq):
        return seq, type(seq)

    # Handle the special case where seq is None
    if seq is None:
        return seq, type(seq)

    # Try to materialise seq into a concrete sequence
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            from collections import deque
            seq_list = list(deque(seq, maxlen=bufsize))
    except TypeError:
        # seq is not iterable; return it as-is
        return seq, type(seq)

    return seq_list, type(seq_list)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is None, use an empty list as a default sequence
    if seq is None:
        seq = []

    # Import here to avoid top-level imports
    from collections.abc import Sequence

    # If seq already implements the Sequence protocol (including str, bytes, tuple, list, etc.),
    # we keep it as-is. For other iterables we try to convert to a list.
    if isinstance(seq, Sequence):
        result_seq = seq
    else:
        try:
            result_seq = list(seq)
        except Exception:
            # If seq is not iterable, fallback to an empty list
            result_seq = []

    return result_seq, type(result_seq)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram)."""
    if other is None:
        # Return current scale, computing it if necessary
        if getattr(self, "_scale", None) is None or recompute:
            try:
                # Try to use bin counts and boundaries if they exist
                counts = getattr(self, "_counts", None)
                if counts is None:
                    counts = getattr(self, "_values", None)
                bounds = getattr(self, "_bins", None)
                if bounds is None:
                    bounds = getattr(self, "_intervals", None)
                if counts is not None and bounds is not None:
                    widths = [bounds[i + 1] - bounds[i] for i in range(len(bounds) - 1)]
                    self._scale = sum(c * w for c, w in zip(counts, widths))
                else:
                    # Fallback: if the histogram behaves like a list of values
                    self._scale = sum(self)
            except Exception:
                # If anything goes wrong, fall back to summing the iterable
                self._scale = sum(self)
        return self._scale

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # If no argument, act as getter
    if other is None:
        return getattr(self, "_scale", None)

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("scale requires a numeric value")

    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise ValueError("cannot rescale a graph with unknown or zero scale")

    factor = other / current_scale
    # Update internal scale
    self._scale = other

    # Rescale last coordinate in the data
    data = getattr(self, "data", None)
    if isinstance(data, (list, tuple)):
        if data:  # non-empty
            # Assume each entry is a sequence where the last element is the y/z/etc coordinate
            for entry in data:
                if isinstance(entry, (list, tuple)) and len(entry) > 0:
                    try:
                        entry[-1] = entry[-1] * factor
                    except Exception:
                        # In case the entry[-1] is not a number
                        pass

    # Rescale corresponding errors if present
    errors = getattr(self, "errors", None)
    if isinstance(errors, (list, tuple)):
        if errors:  # non-empty
            for entry in errors:
                if isinstance(entry, (list, tuple)) and len(entry) > 0:
                    try:
                        entry[-1] = entry[-1] * factor
                    except Exception:
                        pass

    return self  # allow chaining?  (optional)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph representation.

    The histogram object is expected to provide an iterable of bin objects
    accessible through ``hist.bins``.  Each bin should expose at least the
    attributes ``left``, ``right`` and ``content`` (or ``value`` if ``content``
    is not present).  ``make_value`` transforms the bin content into a tuple
    of graph y-values.  The function returns a list of tuples, one for each
    bin, where the first element is the x‑coordinate (determined by
    ``get_coordinate``) and the following elements are the y‑components.
    """
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(
            f"Invalid get_coordinate: {get_coordinate!r}. "
            "Expected one of 'left', 'right' or 'middle'."
        )

    result = []

    for bin_obj in getattr(hist, "bins", []):
        # Find the bin coordinate
        left = getattr(bin_obj, "left", None)
        right = getattr(bin_obj, "right", None)
        if left is None or right is None:
            # Cannot determine coordinate; skip this bin
            continue

        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:
            coord = (left + right) / 2

        # Determine the y-values
        if make_value is None:
            y_val = getattr(bin_obj, "content", None)
            if y_val is None:
                y_val = getattr(bin_obj, "value", None)
            if y_val is None:
                raise ValueError(
                    "Histogram bin does not provide a numeric value."
                )
            point = (coord, y_val)
        else:
            # make_value only receives the numeric content
            y_val = getattr(bin_obj, "content", None)
            if y_val is None:
                y_val = getattr(bin_obj, "value", None)
                if y_val is None:
                    raise ValueError(
                        "Histogram bin does not provide a numeric value."
                    )
            y_vals = make_value(y_val)
            if not isinstance(y_vals, (list, tuple)):
                raise ValueError(
                    "make_value must return an iterable of values."
                )
            if len(y_vals) != len(field_names) - 1:
                raise ValueError(
                    "make_value returned the wrong number of values. "
                    f"Expected {len(field_names)-1}, got {len(y_vals)}."
                )
            point = (coord,) + tuple(y_vals)

        result.append(point)

    # The optional ``scale`` argument is ignored in this general implementation.
    # If the caller wants to propagate a scale attribute they can handle that
    # after receiving the list of points.
    return result

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Define a very small Graph object to hold the result
    class Graph:
        __slots__ = ("scale", "points")

        def __init__(self, scale):
            self.scale = scale
            self.points = []

        def add_point(self, *args):
            # args will be values matching field_names
            if len(args) != len(field_names):
                raise ValueError("Number of arguments does not match field_names")
            point = dict(zip(field_names, args))
            self.points.append(point)

    # Determine the source of bins, either an attribute or the object itself
    try:
        bins = hist.bins if hasattr(hist, "bins") else iter(hist)
    except Exception:
        raise TypeError("hist must be iterable or have a .bins attribute")

    # If scale is True, use histogram's scale attribute if present
    graph_scale = None
    if scale is True:
        if hasattr(hist, "scale"):
            graph_scale = hist.scale
        else:
            graph_scale = None
    elif scale is not None:
        graph_scale = scale

    graph = Graph(graph_scale)

    # Helper to compute coordinate
    def get_x(bin_obj):
        if hasattr(bin_obj, "left") and hasattr(bin_obj, "right"):
            left = bin_obj.left
            right = bin_obj.right
        elif hasattr(bin_obj, "bins"):
            # treat bin_obj as representation of a bin with 'low' and 'high'
            left, right = bin_obj.low, bin_obj.high
        else:
            # if bin_obj is a number, we can't determine coordinate
            raise ValueError("Bin object does not provide left/right edges")

        if get_coordinate == "left":
            return left
        elif get_coordinate == "right":
            return right
        elif get_coordinate == "middle":
            return (left + right) / 2.0
        else:
            raise ValueError(f"Unknown get_coordinate: {get_coordinate}")

    # Iterate over bins
    for bin_obj in bins:
        # Determine the bin content
        if hasattr(bin_obj, "content"):
            content = bin_obj.content
        elif isinstance(bin_obj, (int, float)):
            content = bin_obj
        else:
            # Try to interpret a tuple/list as (content, context)
            try:
                content, _ = bin_obj
            except Exception:
                raise TypeError("Bin must provide numeric content")

        # Apply make_value if provided
        if make_value is not None:
            val = make_value(content)
        else:
            val = content

        # Get coordinate x
        x = get_x(bin_obj)

        # Assemble point
        if isinstance(val, (tuple, list)):
            if len(val) != len(field_names) - 1:
                raise ValueError("Argument for make_value returned wrong number of values")
            graph.add_point(x, *val)
        else:
            # scalar value, expect field_names length 2
            if len(field_names) != 2:
                raise ValueError("Scalar value requires field_names of length 2")
            graph.add_point(x, val)

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    See the module documentation for usage examples and full argument
    description.  The implementation below is intentionally generic: it
    works with histograms that expose their bin contents via a ``bins``
    attribute and their bin boundaries via an ``edges`` attribute, which
    is the most common interface.  If these attributes are not present,
    the function falls back to treating *hist* as an iterable of bins
    and an accompanying iterable of bin edges via an ``edges`` attribute.
    """
    # --- Fetch histogram data -------------------------------------------------
    # Try the most common attribute names; fall back to other possibilities.
    # Provide sensible defaults if anything is missing.
    try:
        bins = list(hist.bins)
    except AttributeError:
        try:
            bins = list(hist)
        except Exception:
            raise TypeError("Histogram must provide iterable 'bins' or be iterable itself")

    try:
        edges = list(hist.edges)
    except AttributeError:
        try:
            edges = list(hist.bin_edges)
        except Exception:
            raise AttributeError(
                "Histogram must provide 'edges' or 'bin_edges' attributes"
            )

    if len(edges) != len(bins) + 1:
        raise ValueError(
            "The number of edges must be one more than the number of bins"
        )

    # --- Validate input -------------------------------------------------------
    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    if not isinstance(field_names, (tuple, list)):
        raise TypeError("field_names must be a sequence")
    # The first field will always be x, the rest correspond to the
    # value(s) returned by make_value or the raw bin contents.
    base_dim = 1 + (len(bins) if make_value is None else 1)
    if len(field_names) != base_dim:
        # Allow make_value to return a tuple; we will not know its length
        # ahead of time, so we skip strict checking.
        result = None

    # --- Build graph data ----------------------------------------------------
    graph_points = []

    for i, content in enumerate(bins):
        left_edge, right_edge = edges[i], edges[i + 1]

        # Determine the x coordinate.
        if get_coordinate == "left":
            x_coord = left_edge
        elif get_coordinate == "right":
            x_coord = right_edge
        else:  # "middle"
            x_coord = 0.5 * (left_edge + right_edge)

        # Convert the bin content into the value(s) for the graph point.
        if make_value is None:
            value = content
        else:
            value = make_value(content)

        # Ensure value is iterable for tuple concats.
        if isinstance(value, (tuple, list)):
            value_tuple = tuple(value)
        else:
            value_tuple = (value,)

        # Combine into a single point: (x, y1, y2, ...)
        point = (x_coord,) + value_tuple
        graph_points.append(point)

    # --- Determine result scale ------------------------------------------------
    result_scale = scale
    if result_scale is True:
        result_scale = getattr(hist, "scale", None)

    # --- Return a very lightweight graph representation ----------------------
    # The actual library might provide a Graph class; for this generic
    # implementation we return a dictionary containing the data.
    return {
        "points": graph_points,
        "fields": field_names,
        "scale": result_scale,
    }

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # `iface` must be a class or interface (i.e., a type).
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface type")

    # Determine if candidate is a class or an instance.
    candidate_is_class = isinstance(candidate, type)

    # Basic checks: subclass or instance.
    if not tentative:
        if candidate_is_class:
            if not issubclass(candidate, iface):
                raise TypeError(f"{candidate!r} does not subclass {iface!r}")
        else:
            if not isinstance(candidate, iface):
                raise TypeError(f"{candidate!r} is not an instance of {iface!r}")

    # If tentative, perform a relaxed check that the candidate
    # provides the attributes/methods defined by `iface`.
    if tentative:
        # Iterate over public attributes of the interface.
        for name in dir(iface):
            # Skip special/magic attributes.
            if name.startswith("__") and name.endswith("__"):
                continue
            iface_attr = getattr(iface, name)
            # If the interface attribute is callable, ensure candidate has a callable
            if callable(iface_attr):
                if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
                    raise TypeError(f"{candidate!r} lacks method '{name}' required by {iface!r}")
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine whether candidate is a class or an instance
    if isinstance(candidate, type):
        candidate_cls = candidate
    else:
        candidate_cls = type(candidate)

    # First, try the straightforward subclass check
    try:
        if issubclass(candidate_cls, iface):
            return True
    except TypeError:
        # Not a class; continue with attribute checks
        pass

    # Gather the public callable members of the interface
    interface_methods = [
        name for name in dir(iface)
        if callable(getattr(iface, name)) and not name.startswith('_')
    ]

    # Ensure the candidate has all required methods
    for name in interface_methods:
        if not hasattr(candidate_cls, name):
            return False

    # If tentative, we are less strict about abstract methods
    if tentative:
        return True

    # For non-tentative, check that required methods are actually implemented
    for name in interface_methods:
        iface_method = getattr(iface, name)
        candidate_method = getattr(candidate_cls, name, None)
        if candidate_method is None:
            return False
        # Optionally check signatures if needed (omitted for brevity)
        # For simplicity, we assume presence of a callable with same name
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The *iface* argument represents an interface, usually expressed as a class or
    protocol. The *candidate* may be a class, an instance of a class, or a string
    containing a fully‑qualified class path (e.g. ``'module.Class'``).

    The function returns ``True`` if the candidate appears to satisfy the
    interface; otherwise ``False``.  The *tentative* flag suppresses import
    errors; if set to ``True`` a missing or invalid candidate simply results in
    ``False`` rather than an exception.

    Notes
    -----
    * If both ``iface`` and ``candidate`` are classes, ``issubclass(candidate, iface)``
      is used.
    * If ``iface`` is an instance and ``candidate`` is an instance, ``isinstance(candidate, iface)``
      is used.
    * If ``iface`` is a class and ``candidate`` is an instance, ``isinstance(candidate, iface)``
      is used.
    * If ``candidate`` is a string, it is interpreted as a fully‑qualified
      class path and imported lazily.  Import errors are ignored when *tentative*
      is true.
    * As a fallback, the function checks that the candidate (class or instance)
      defines all public methods and attributes that the interface declares.
    """

    import importlib, inspect, sys

    # Resolve candidate if it is a string
    if isinstance(candidate, str):
        try:
            module_path, _, class_name = candidate.rpartition('.')
            if not module_path:
                raise ImportError  # e.g. just "ClassName" without module
            module = importlib.import_module(module_path)
            candidate_cls = getattr(module, class_name)
        except (ImportError, AttributeError) as exc:
            if tentative:
                return False
            else:
                raise exc
        candidate = candidate_cls

    # Helper to get interface's members (public methods/attributes)
    def get_iface_members(obj):
        return {
            name: member
            for name, member in inspect.getmembers(obj)
            if not name.startswith('_')
        }

    # Class‑to‑class
    if isinstance(candidate, type) and isinstance(iface, type):
        return issubclass(candidate, iface)

    # Instance vs class or instance
    if isinstance(iface, type) and not isinstance(candidate, type):
        return isinstance(candidate, iface)

    if isinstance(iface, type) and isinstance(candidate, type):
        # Already handled subclass but check if candidate might be instance later
        return False

    # If iface is an instance (rare), use isinstance
    if not isinstance(iface, type) and not isinstance(candidate, type):
        return isinstance(candidate, type(iface))

    # Fallback: member existence check
    iface_members = get_iface_members(iface)
    candidate_members = get_iface_members(candidate)

    for name in iface_members:
        if name not in candidate_members:
            return False
        # Optionally check that callables are compatible
        iface_member = iface_members[name]
        cand_member = candidate_members[name]
        if inspect.isroutine(iface_member) and inspect.isroutine(cand_member):
            # Simple check: signatures match
            try:
                sig_if = inspect.signature(iface_member)
                sig_cand = inspect.signature(cand_member)
                if sig_if != sig_cand:
                    return False
            except ValueError:
                # If can't inspect signature, skip check
                pass
        elif not inspect.isroutine(iface_member) and not inspect.isroutine(cand_member):
            # For attributes, we could check types if available
            if hasattr(iface_member, '__class__'):
                if not isinstance(cand_member, type(iface_member)):
                    return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a metaclass")
        return explicit_mc
    mcls = type
    for base in bases:
        m = type(base)
        if mcls is m or issubclass(mcls, m):
            continue
        if issubclass(m, mcls):
            mcls = m
        else:
            raise TypeError("metaclass conflict: cannot determine a common metaclass")
    return mcls

