    # Private message indicators
    private_keys = {"to", "recipient", "receiver", "private_message"}
    if any(k in data for k in private_keys):
        return True

    # Legacy payload indicator
    legacy_keys = {"legacy_payload", "legacy", "relays", "old_format"}
