def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Use ISO 8601 format ending with 'Z' for UTC time
    # If the datetime is naive, assume UTC.
    try:
        import datetime
    except Exception:
        # Fallback to simple string representation if datetime module is not available
        return str(dt)
    if getattr(dt, "tzinfo", None) is None:
        # Assume UTC for naive datetime
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    # Convert to UTC and format to seconds precision
    utc_dt = dt.astimezone(datetime.timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The format used is ISO 8601 with a 'Z' suffix to indicate UTC:
    "YYYY-MM-DDTHH:MM:SSZ".
    If the provided datetime is timezone-aware, it is converted to UTC
    before formatting. If it is naive, it is assumed to already be UTC.
    """
    # Ensure we have a datetime-like object
    if not hasattr(dt, "strftime") or not hasattr(dt, "tzinfo"):
        raise TypeError("format_dt expects a datetime-like object")

    # Convert to UTC if timezone-aware; compute offset manually to avoid imports
    if dt.tzinfo is not None:
        offset = dt.utcoffset()
        if offset is not None:
            # Subtract the offset to get UTC
            utc_dt = dt - offset
        else:
            utc_dt = dt
    else:
        utc_dt = dt

    # Format without microseconds and with trailing Z
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

