    :arg host: Host to retrieve from
    :returns: ``XRD`` instance (parsed XML Element) or None if not retrievable
    """
    import urllib.request
    import xml.etree.ElementTree as ET

    # Attempt HTTPS first, then fallback to HTTP if necessary
    for scheme in ("https", "http"):
        url = f"{scheme}://{host}/.well-known/host-meta"
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                data = resp.read()
                try:
                    return ET.fromstring(data)
                except ET.ParseError:
                    return None
        except Exception:
            # Continue to the next scheme
            continue

    # If all attempts fail, return None
    return None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    import requests
    try:
        method_lower = (method or "post").lower()
        if method_lower not in {"post", "put", "delete", "patch", "get"}:
            raise ValueError(f"Unsupported HTTP method: {method}")

        request_func = getattr(requests, method_lower)
        response = request_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """

    try:
        # Use the provided method (defaulting to POST) to send the data
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        # Return None for status code and the exception instance
        return (None, exc)

