def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Nothing to do on non-dict or missing include
    if not isinstance(parser_dict, dict) or 'include' not in parser_dict:
        return parser_dict

    includes = parser_dict['include']

    # Normalize includes to a list
    if isinstance(includes, str):
        includes = [includes]
    elif not isinstance(includes, (list, tuple)):
        try:
            includes = list(includes)
        except Exception:
            includes = [includes]

