        # Attempt to load the included spec dictionary
        try:
            inc_dict = self._load_group(inc_name)
        except Exception:
            continue

        if not isinstance(inc_dict, dict):
            continue

        # Resolve nested includes in the included dictionary
        self._include_groups(inc_dict)

        # Merge the included dictionary into the current one
        deep_merge(parser_dict, inc_dict)

    # Clean up the include directive to avoid repeated processing
    parser_dict.pop('include', None)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.get("include")
    if not includes:
        return parser_dict

