    if isinstance(includes, dict):
        includes = [includes]
    elif not isinstance(includes, (list, tuple)):
        includes = []

    # Ensure components/groups structure exists
    components = parser_dict.setdefault("components", {})
    groups = components.setdefault("groups", {})

    for inc in includes:
        if isinstance(inc, str):
            inc = {"file": inc}
        file_path = inc.get("file")
        if not file_path:
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
