        if isinstance(spec, dict):
            for name, meta in spec.items():
                # Prefer an explicit default if present
                if isinstance(meta, dict):
                    if "default" in meta:
                        defaults[name] = meta["default"]
                    elif "value" in meta:
                        defaults[name] = meta["value"]
                else:
                    # If the spec entry is a direct value, use it
                    defaults[name] = meta
        else:
            # Fallback: if spec is not a dict, no defaults can be extracted
            pass
        return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}

    def resolve(name):
        # First look in self.spec
        spec_val = None
        if hasattr(self, 'spec'):
            if isinstance(self.spec, dict):
                if name in self.spec:
                    spec_val = self.spec[name]
            else:
                if hasattr(self.spec, name):
                    spec_val = getattr(self.spec, name)
        # Fallback to attribute on self
        if spec_val is not None:
            return spec_val
        return getattr(self, name, None)

    # Determine argument names: prefer self.args, else annotations
    arg_names = getattr(self, 'args', None)
    if not arg_names:
        if hasattr(self.__class__, '__annotations__'):
            arg_names = list(self.__class__.__annotations__.keys())
        else:
            arg_names = []

    for name in arg_names:
        defaults[name] = resolve(name)

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    spec = getattr(self, 'spec', {})
    # Existing values that have been supplied by the user
    provided = getattr(self, 'values', {}) or {}
    if not isinstance(provided, dict):
        provided = {}
    provided_keys = set(provided.keys())
    for key, spec_def in spec.items():
        # Skip keys that already have a supplied value
        if key in provided_keys:
            continue
        if isinstance(spec_def, dict):
            # Use explicit default if defined
            if 'default' in spec_def:
                defaults[key] = spec_def['default']
            # Optionally fetch from environment variable
            if spec_def.get('source') == 'env':
                env_var = spec_def.get('env_var', key.upper())
                import os
                value = os.getenv(env_var)
                if value is not None:
                    defaults[key] = value
        else:
            # If spec value is not a dict, treat it as a default itself
            defaults[key] = spec_def
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Get the list of argument specs
    try:
        args = self.spec.get('args', [])
    except AttributeError:
        args = getattr(self.spec, 'args', [])
    for arg in args:
        # Support both dict- and object-based specs
        if isinstance(arg, dict):
            name = arg.get('name')
            if not name:
                continue
            val = arg.get('default')
        else:
            name = getattr(arg, 'name', None)
            if not name:
                continue
            val = getattr(arg, 'default', None)
        if val is not None:
            defaults[name] = val
    # Merge any additional default sources specified in the spec
    try:
        sources = self.spec.get('sources', [])
    except AttributeError:
        sources = getattr(self.spec, 'sources', [])
    for src in sources:
        if isinstance(src, dict):
            defaults.update(src)
    # Store on the instance and return
    self.defaults = defaults
    return defaults

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Returns a dictionary containing defaults for arguments
    that were not explicitly provided in ``self.args`` or ``self.options``.
    """
    # Ensure spec arguments mapping exists
    if not hasattr(self, "spec") or not isinstance(self.spec, dict):
        return {}

    # The expected location of argument definitions
    arguments = self.spec.get("arguments", {})

    # Container for resolved defaults
    defaults = {}

    for arg_name, meta in arguments.items():
        # Skip if value already supplied via args or options
        if hasattr(self, "args") and arg_name in self.args:
            continue
        if hasattr(self, "options") and arg_name in self.options:
            continue

        # 1. Direct default value in the spec
        if isinstance(meta, dict) and "default" in meta:
            defaults[arg_name] = meta["default"]
            continue

        # 2. Environment variable (if specified)
        if isinstance(meta, dict):
            env_key = meta.get("env")
            if env_key:
                try:
                    import os  # Imported here to avoid module‑level imports
                    value = os.environ.get(env_key)
                    if value is not None:
                        # Perform basic type conversion if type is specified
                        if "type" in meta:
                            target_type = meta["type"]
                            if target_type is bool:
                                value = value.lower() in ("1", "true", "yes", "on")
                            elif target_type is int:
                                value = int(value)
                            elif target_type is float:
                                value = float(value)
                        defaults[arg_name] = value
                        continue
                except Exception:
                    # Silently ignore any error and proceed
                    pass

        # 3. Default source callable
        if isinstance(meta, dict) and "default_source" in meta:
            source = meta["default_source"]
            if callable(source):
                try:
                    defaults[arg_name] = source()
                    continue
                except Exception:
                    pass

        # 4. Required argument without a default – raise an error
        if isinstance(meta, dict) and meta.get("required", False):
            spec_name = self.spec.get("name", "<unknown spec>")
            raise ValueError(
                f"Required argument '{arg_name}' for spec '{spec_name}' "
                "is missing and has no default value."
            )

    return defaults

