def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # The set of deprecated argument names should be defined on the instance.
    # Default to empty set if not present.
    deprecated = getattr(self, 'deprecated_args', set())

    # Check command‑line arguments first
    for arg_name in cli_args:
        if arg_name in deprecated:
            print(f"WARNING: The command‑line option '{arg_name}' is deprecated and will be ignored.")

    # Check answer file arguments
    for arg_name in answer_file_args:
        if arg_name in deprecated:
            print(f"WARNING: The argument '{arg_name}' in the answer file is deprecated and will be ignored.")

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Attempt to retrieve options from the most common attribute names.  If the
    # object does not expose any, fall back to an empty list.
    if hasattr(self, "cmd_option_specs"):
        opts = getattr(self, "cmd_option_specs", {})
    elif hasattr(self, "parser_options"):
        opts = getattr(self, "parser_options", {})
    elif hasattr(self, "command_option_specs"):
        opts = getattr(self, "command_option_specs", {})
    else:
        opts = {}

    # Ensure we always work with a dictionary mapping command names to
    # option lists.  If the attribute is already a dict of options, use it
    # directly; otherwise, treat it as a list or other iterable.
    if isinstance(opts, dict):
        opt_list = opts.get(command_name, [])
    else:
        # In the unlikely case that the attribute is not a dict, assume
        # it is itself a list of options and return it if the command_name
        # matches some indicator within the entries.  For safety, return an
        # empty list if we cannot determine the mapping.
        opt_list = []

    # Finally, make sure we always return a list.
    if not isinstance(opt_list, list):
        try:
            opt_list = list(opt_list)
        except TypeError:
            opt_list = []

    return opt_list

