    # Attempt to locate the command's specification in the registry.
    # The registry is assumed to be stored in `self._specs`. Each command
    # specification contains an `options` mapping from option names to
    # their corresponding specification objects.
    try:
        cmd_spec = self._specs.get(command_name)
        if not cmd_spec:
            raise KeyError
        options = cmd_spec.get('options', {})
        if argument_name not in options:
            raise KeyError
        return options[argument_name]
    except KeyError:
        raise KeyError(
            f"Option specification for '{argument_name}' in command '{command_name}' not found."
        ) from None

