def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Prefer a dictionary of command specifications stored on the instance.
    # The structure is assumed to be:
    #   self.commands = {
    #       "cmd_name": {
    #           "options": {"opt_name": spec_obj, ...},
    #           "arguments": {"arg_name": spec_obj, ...}
    #       }, ...
    # }
    # or alternatively a single dict self.specs with the same nesting.
    specs = getattr(self, 'commands', None) or getattr(self, 'specs', None)
    if not isinstance(specs, dict):
        return None
    cmd_spec = specs.get(command_name)
    if not isinstance(cmd_spec, dict):
        return None
    # Look under "options" first, then "arguments" as a fallback.
    option_spec = cmd_spec.get('options', {}).get(argument_name)
    if option_spec is not None:
        return option_spec
    argument_spec = cmd_spec.get('arguments', {}).get(argument_name)
    return argument_spec

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        if args is None:
            return []

        silent_args = []

        # If args is a dict (common in simple parsers)
        if isinstance(args, dict):
            for key in args:
                if key.startswith("_"):
                    silent_args.append(key)

        # If args is an argparse.Namespace or similar
        else:
            # Many namespaces expose their data via __dict__ attribute
            try:
                data = vars(args)
            except TypeError:
                # If vars fails, fallback to empty list
                data = {}
            for key in data:
                if key.startswith("_"):
                    silent_args.append(key)

        return silent_args

def get_silent_args(self, args):
        """
        list of silenced argument

        :param args: The received arguments.
        :return: list, silenced argument names
        """
        if not args:
            return []

        silent_names = []
        # Attempt to treat args as a mapping of name -> value
        try:
            items = args.items()
        except AttributeError:
            # If args is not a dict-like object, we cannot determine silent arguments
            return silent_names

        for name, value in items:
            # Consider an argument "silenced" if its value is None or False
            if value is None or value is False:
                silent_names.append(name)

        return silent_names

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, "requires", None)
    if required is None:
        return True
    missing = [key for key in required if key not in args or args[key] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_args = []

        for opt in options_spec:
            opt_name = opt.get('name')
            if not opt_name:
                continue

            cond = opt.get('required_when')
            if cond is None:
                continue

            # Cond could be a dict, list of dicts, callable, or any truthy value
            try:
                if callable(cond):
                    # If it's a callable, pass args as argument
                    if cond(args):
                        required_args.append(opt_name)
                elif isinstance(cond, dict):
                    # Simple dict of key: expected_value
                    if all(args.get(k) == v for k, v in cond.items()):
                        required_args.append(opt_name)
                elif isinstance(cond, list):
                    # List may contain multiple dict conditions
                    for c in cond:
                        if isinstance(c, dict) and all(args.get(k) == v for k, v in c.items()):
                            required_args.append(opt_name)
                            break
                else:
                    # Any truthy value is considered as required
                    if cond:
                        required_args.append(opt_name)
            except Exception:
                # If evaluation fails, ignore this option
                pass

        return required_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Helper to fetch a value from args which could be a dict or an object.
    def _get_val(key):
        if isinstance(args, dict):
            return args.get(key)
        return getattr(args, key, None)

    # Evaluate a condition.  A condition may be a callable, a dict, a list/tuple,
    # a string referring to another argument, or a simple truthy value.
    def _eval_cond(cond):
        if callable(cond):
            return bool(cond(args))
        if isinstance(cond, dict):
            for k, v in cond.items():
                val = _get_val(k)
                if isinstance(v, (list, tuple)):
                    if val not in v:
                        return False
                else:
                    if val != v:
                        return False
            return True
        if isinstance(cond, (list, tuple)):
            return all(_eval_cond(c) for c in cond)
        if isinstance(cond, str):
            return bool(_get_val(cond))
        return bool(cond)

    result = []
    for opt in options_spec:
        # Accept various spec naming conventions.
        opt_name = getattr(opt, 'name', None)
        if opt_name is None:
            opt_name = getattr(opt, 'option', None)
        if not opt_name:
            continue
        required_when = getattr(opt, 'required_when', None)
        if required_when is None:
            continue
        try:
            if _eval_cond(required_when):
                result.append(opt_name)
        except Exception:
            # If evaluation fails, treat as not required.
            continue
    return result

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        # Grab the condition callable if present
        cond = opt.get('required_when')
        if not cond:
            continue
        try:
            present = bool(cond(args))
        except Exception:
            present = False
        if present:
            # Prefer name field; fall back to long_name or any other identifier
            name = opt.get('name')
            if name is None:
                name = opt.get('long_name')
            if name:
                required.append(name)
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_when_args = []

        # Ensure options_spec is iterable; convert list of dicts to dict keyed by name if needed
        if isinstance(options_spec, list):
            spec_dict = {}
            for opt in options_spec:
                opt_name = opt.get('name') or opt.get('option', None)
                if opt_name:
                    spec_dict[opt_name] = opt
            options_spec = spec_dict

        for opt_name, opt_spec in options_spec.items():
            if not isinstance(opt_spec, dict):
                continue
            if 'required_when' in opt_spec and opt_spec['required_when']:
                cond = opt_spec['required_when']

                # If required_when is a callable, evaluate it with args
                if callable(cond):
                    try:
                        if cond(args):
                            required_when_args.append(opt_name)
                        continue
                    except Exception:
                        # if callable fails, skip
                        continue

                # If required_when is a dict mapping other argument names to values
                if isinstance(cond, dict):
                    match = True
                    for key, expected in cond.items():
                        if key not in args:
                            match = False
                            break
                        val = args[key]
                        # expected may be a set/list of acceptable values
                        if isinstance(expected, (list, tuple, set)):
                            if val not in expected:
                                match = False
                                break
                        else:
                            if val != expected:
                                match = False
                                break
                    if match:
                        required_when_args.append(opt_name)
                        continue

                # If required_when is a boolean True -> always required
                if cond is True:
                    required_when_args.append(opt_name)

        return required_when_args

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # If the instance has a 'lengths' mapping that specifies maximum
        # allowed lengths for each argument name, validate against it.
        lengths = getattr(self, "lengths", None)
        if not lengths:
            return

        for name, value in args.items():
            max_len = lengths.get(name)
            if max_len is None:
                continue
            try:
                # Only validate objects that have a length (e.g., strings, lists, dicts, etc.)
                val_len = len(value)
            except Exception:
                # If length can’t be determined, skip validation for this value.
                continue
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}"
                )

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # If no length limits defined, assume everything is fine
    if not hasattr(self, 'length_limits') or not isinstance(self.length_limits, dict):
        return True
    # Iterate over known length limits
    for key, max_len in self.length_limits.items():
        # Skip if the key is not present in arguments
        if key not in args:
            continue
        value = args[key]
        # Skip None values
        if value is None:
            continue
        try:
            # Some values may not support len (e.g., ints). If it does, check length
            if len(value) > max_len:
                raise ValueError(f"Argument '{key}' exceeds maximum length of {max_len}.")
        except TypeError:
            # Value does not support len; ignore
            continue
    return True

def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.
        If an argument exceeds its allowed length, raise a ValueError.

        The method expects a mapping or iterable of argument pairs.
        The allowed maximum length for each argument should be defined in a
        dictionary `self.max_lengths`, where the keys are argument names
        and the values are integer maximum lengths.
        """
        # Determine the container type and iterate through arguments
        if isinstance(args, dict):
            iterable = args.items()
        elif isinstance(args, (list, tuple)):
            # Handle list/tuple of (name, value) pairs
            iterable = args
        else:
            # Unsupported type; nothing to validate
            return

        for name, value in iterable:
            # Get the maximum length for this argument name, if defined
            max_len = getattr(self, "max_lengths", {}).get(name)
            if max_len is None:
                # No length restriction specified; skip this argument
                continue

            # Only string-like values have a length to check
            if isinstance(value, str):
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{name}' exceeds maximum length of {max_len}. "
                        f"Received length: {len(value)}."
                    )
            # If the value is a collection (list/tuple), we may want to check
            # each element's length if elements are strings.
            elif isinstance(value, (list, tuple)):
                for idx, elem in enumerate(value):
                    if isinstance(elem, str) and len(elem) > max_len:
                        raise ValueError(
                            f"Element {idx} of argument '{name}' exceeds maximum "
                            f"length of {max_len}. Received length: {len(elem)}."
                        )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary so we can inspect key/value pairs
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    # Iterate over each argument and compare its string length against a configured maximum
    for key, value in args.items():
        # skip validation for missing values (None)
        if value is None:
            continue
        max_len = None
        # Try to obtain the maximum length from several possible locations:
        # 1. a predefined `max_lengths` dictionary on the instance
        if hasattr(self, "max_lengths") and isinstance(self.max_lengths, dict):
            max_len = self.max_lengths.get(key)
        # 2. an attribute named `<key>_max_length` on the instance
        if max_len is None:
            attr_name = f"{key}_max_length"
            if hasattr(self, attr_name):
                max_len = getattr(self, attr_name)
        # If a maximum length is defined, enforce it
        if max_len is not None:
            try:
                length = len(str(value))
            except TypeError:
                # If the value is not coercible to a string, skip the check
                continue
            if length > max_len:
                raise ValueError(
                    f"Argument '{key}' exceeds maximum length of {max_len}: '{value}'"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.

    :raises ValueError: If an argument value is not among the allowed choices.
    """
    for arg_name, arg_value in args.items():
        # Try to get the argument definition; its structure may vary
        arg_def = None
        if hasattr(self, "_arg_map"):
            arg_def = self._arg_map.get(arg_name)
        elif hasattr(self, "_cmd") and hasattr(self._cmd, "arg_map"):
            arg_def = self._cmd.arg_map.get(arg_name)

        # If there is no definition, skip validation for this arg
        if arg_def is None:
            continue

        # Attempt to extract the choices attribute; it may be a property or dict entry
        choices = None
        if isinstance(arg_def, dict):
            choices = arg_def.get("choices")
        else:
            choices = getattr(arg_def, "choices", None)

        # Skip if no choices are defined
        if choices is None:
            continue

        # Normalize choices to an iterable if it's a string (allowing commas)
        if not isinstance(choices, (list, tuple, set)):
            try:
                # Try converting to list if it's a comma-separated string
                if isinstance(choices, str):
                    choices = [c.strip() for c in choices.split(",")]
                else:
                    # Fallback: wrap the single choice in a list
                    choices = [choices]
            except Exception:
                # If conversion fails, treat as a single item list
                choices = [choices]

        # Validate the argument value is within the allowed choices
        if arg_value not in choices:
            raise ValueError(
                f'Invalid value "{arg_value}" for argument "{arg_name}". '
                f"Allowed choices are: {', '.join(map(str, choices))}."
            )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # If there are no arguments or no choices defined, nothing to validate
        if not args or not hasattr(self, "_choices"):
            return

        for name, value in args.items():
            # Skip arguments that have no defined choices
            if name not in getattr(self, "_choices", {}):
                continue

            allowed = self._choices[name]

            # Determine if this option accepts multiple values
            multiple = getattr(self, "_multiple", {}).get(name, False)

            if multiple:
                # Ensure the value is an iterable of expected type
                if not isinstance(value, (list, tuple)):
