def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # If the class does not keep definitions, nothing to validate
        if not hasattr(self, 'arg_definitions'):
            return

        for name, value in args.items():
            # skip arguments without a definition
            arg_def = self.arg_definitions.get(name)
            if not arg_def:
                continue

            # Skip if no choices are defined
            choices = arg_def.get('choices')
            if not choices:
                continue

            # Skip None values (optional arguments)
            if value is None:
                continue

            # Determine if the value is a sequence that should be iterated
            # (e.g., nargs='+' or a list/tuple). Treat strings as scalars.
            is_collection = isinstance(value, (list, tuple, set)) and not isinstance(value, str)

            # If choices is a callable, ask it if the value is valid
            if callable(choices):
                if not choices(value):
                    raise ValueError(
                        f"Argument '{name}' has an invalid choice: {value}. "
                        f"Supported choices must satisfy the provided callback."
                    )
                continue

            # Normalize choices to a set for fast lookup
            choice_set = set(choices) if not isinstance(choices, (set, frozenset)) else choices

            if is_collection:
                for v in value:
                    if v not in choice_set:
                        raise ValueError(
                            f"Argument '{name}' has an invalid choice: {v}. "
                            f"Allowed choices are: {choice_set}"
                        )
            else:
                if value not in choice_set:
                    raise ValueError(
                        f"Argument '{name}' has an invalid choice: {value}. "
                        f"Allowed choices are: {choice_set}"
                    )

