def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # If no arguments were supplied, nothing to validate.
    if not args:
        return

    # Attempt to locate the definitions that may contain choice information.
    # The implementation is defensive and attempts to handle a few common
    # patterns that a command‑line parser might use.

    # 1. If the object has a mapping of argument names to definition dicts,
    #    each dict may contain a ``choices`` key.
    arg_defs = getattr(self, "_arg_definitions", {})
    if not isinstance(arg_defs, dict):
        arg_defs = {}

    # 2. If the object stores a list of argument objects (e.g. argparse
    #    ``ArgumentParser`` style), each object may have ``name`` and ``choices``.
    arg_objects = getattr(self, "_args", [])

    # Check patterns from #1
    for arg_name, definition in arg_defs.items():
        if not isinstance(definition, dict):
            continue
        if "choices" not in definition:
            continue
        # Skip if the argument was not supplied.
        if arg_name not in args:
            continue
        choice_set = definition["choices"]
