                        f"Expected one of {choice_set}, got {v}"
                    )
        else:
            if value not in choice_set:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}'. "
                    f"Expected one of {choice_set}, got {value}"
                )

    # Check patterns from #2
    for arg_obj in arg_objects:
        # Skip objects that do not expose a ``choices`` attribute.
        if not hasattr(arg_obj, "choices"):
            continue
        # Resolve the name; allow multiple possible attribute names.
        arg_name = getattr(arg_obj, "name", None) or getattr(arg_obj, "dest", None)
        if not arg_name:
            continue
        if arg_name not in args:
            continue
        choice_set = arg_obj.choices
        if not isinstance(choice_set, (list, tuple, set)):
            choice_set = {choice_set}
        value = args[arg_name]
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choice_set:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}'. "
                        f"Expected one of {choice_set}, got {v}"
                    )
        else:
            if value not in choice_set:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}'. "
                    f"Expected one of {choice_set}, got {value}"
                )

