def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build a simple complex argument type based on ``spec_option``.
    ``spec_option`` is expected to be a mapping of field names to either
    a type (int, float, str, bool) or a mapping ``{'type': <type>, 'default': <value>}``.
    The returned type is a plain ``object`` subclass with a custom ``__init__``,
    ``__repr__`` and documentation string that describes it.
    """
    # Map accepted type names to real types
    _type_map = {
        int: int,
        float: float,
        str: str,
        bool: bool,
    }

    # Resolve fields and defaults
    field_specs = {}
    for field, spec in spec_option.items():
        if isinstance(spec, dict):
            t = spec.get('type', str)
            dflt = spec.get('default', None)
        else:
            t = spec
            dflt = None
        # Convert string names to actual types if needed
        t = _type_map.get(t, t if isinstance(t, type) else str)
        field_specs[field] = (t, dflt)

    # Constructor: convert supplied values using the field type
    def __init__(self_local, **kwargs):
        for f_name, (f_type, f_default) in field_specs.items():
            raw_val = kwargs.get(f_name, f_default)
            if raw_val is not None:
                try:
                    if f_type is bool:
                        if isinstance(raw_val, str):
                            raw_val = raw_val.lower() in ('true', '1', 'yes')
                        else:
                            raw_val = bool(raw_val)
                    else:
                        raw_val = f_type(raw_val)
                except Exception as exc:
                    raise ValueError(f\"Invalid value for option '{option_name}': field '{f_name}'\") from exc
            setattr(self_local, f_name, raw_val)

    # Representation for debugging / testing
    def __repr__(self_local):
        parts = [f"{name}={getattr(self_local, name)!r}" for name in field_specs]
        return f"{type_name}({', '.join(parts)})"

    # Build the new type
    cls_dict = {
        "__init__": __init__,
        "__repr__": __repr__,
        "__module__": __name__,
        "__doc__": f"Complex argument type {type_name} for command '{subcommand}' option '{option_name}'.",
        "_fields": field_specs,
    }
    complex_type = type(type_name, (object,), cls_dict)

    return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list/dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Determine the type of args and iterate accordingly.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Assume iterable of (key, value) tuples.
            items = [(k, v) for k, v in args]
        except TypeError:
            # If it's a single key-value pair or unsupported type, treat as empty.
            items = []

    for key, val in items:
        if isinstance(key, str) and (key.startswith("control_") or key == "control"):
            control_args[key] = val
        else:
            # All other keys are considered nested/custom arguments.
            nested_args[key] = val

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return
    # If extra_vars is a dict, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    # If it's a list/tuple, iterate through elements
    elif isinstance(extra_vars, (list, tuple)):
        for ev in extra_vars:
            if isinstance(ev, dict):
                vars_dict.update(ev)
            elif isinstance(ev, str) and '=' in ev:
                k, v = ev.split('=', 1)
                vars_dict[k] = v
    # Handle a single string argument
    elif isinstance(extra_vars, str) and '=' in extra_vars:
        k, v = extra_vars.split('=', 1)
        vars_dict[k] = v
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    def _parse_value(val):
        """Parse a string into a Python literal if possible."""
        # Strip surrounding whitespace
        s = val.strip()
        # Handle <None> representations
        if s in ("None", "null", "NULL"):
            return None
        # Handle booleans
        lower = s.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        # Try integer
        try:
            return int(s)
        except ValueError:
            pass
        # Try float
        try:
            return float(s)
        except ValueError:
            pass
        # Return as string if nothing matched
        return s

    if not extra_vars:
        return vars_dict

    # If extra_vars is a mapping, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        # Accept list/tuple of items
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # Expect key=value; if no '=', ignore
                if '=' in item:
                    key, val = item.split('=', 1)
                    key = key.strip()
                    val = _parse_value(val)
                    vars_dict[key] = val
                else:
                    # Treat as flag: boolean True
                    key = item.strip()
                    if key:
                        vars_dict[key] = True
            else:
                # Unsupported type: ignore
                continue
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict")
        if not extra_vars:
            return
        for var in extra_vars:
            if isinstance(var, dict):
                vars_dict.update(var)
            elif isinstance(var, str) and '=' in var:
                key, value = var.split('=', 1)
                # Attempt to interpret the value as JSON if possible; otherwise keep as string
                try:
                    parsed = __import__('json').loads(value)
                except Exception:
                    parsed = value
                vars_dict[key] = parsed
        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
