            vars_dict[key] = parsed_val
    return vars_dict

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs Ansible CLI with the provided variables.

    Args:
        cli_args (list): List of command-line arguments for ansible-playbook.
        vars_dict (dict): Dictionary of variables to pass as --extra-vars.
        ir_workspace: Infrared Workspace object representing the active workspace.
        ir_plugin: InfraredPlugin instance for the current plugin.

    Returns:
        dict: Parsed JSON result returned by Ansible.

    Raises:
        RuntimeError: If the Ansible command fails to execute.
    """
    import json
    import shlex
    from subprocess import run, CalledProcessError

    # Build the ansible-playbook command
    cmd = ["ansible-playbook"] + list(map(str, cli_args))

    # Add the --extra-vars argument if vars_dict is provided
    if vars_dict:
        extra_vars = json.dumps(vars_dict)
        cmd += ["--extra-vars", extra_vars]

    # The Infrared API usually provides a helper to run CLI commands
    # Use the plugin's runner if available, otherwise fall back to subprocess
    try:
        # Infrared plugins expose a `run_cli` method that can capture output
        if hasattr(ir_plugin, "run_cli"):
            result = ir_plugin.run_cli(cmd, ir_workspace, be_verbose=True)
            # Infrared returns stdout as a string; parse as JSON if possible
            try:
                return json.loads(result.stdout)
            except Exception:
                return {"stdout": result.stdout, "stderr": result.stderr, "returncode": result.returncode}
        else:
            # Fallback to subprocess.run if no IR helper is available
            completed = run(cmd, capture_output=True, text=True, check=True)
            # Attempt to parse the output as JSON
            try:
                return json.loads(completed.stdout)
            except Exception:
                return {"stdout": completed.stdout, "stderr": completed.stderr, "returncode": completed.returncode}
    except CalledProcessError as exc:
        # If the command failed, convert the error to a dict for consistency
        return {"stdout": exc.stdout, "stderr": exc.stderr, "returncode": exc.returncode}
    except Exception as exc:
        raise RuntimeError(f"Ansible playbook execution failed: {exc}") from exc

