    """
    import os
    import json
    # yaml is optional; import lazily
    try:
        import yaml
    except Exception:
        yaml = None

    # Attempt to locate a plugin spec file
    spec_filenames = [
        "plugin_spec.json", "spec.json", "plugin.json",
        "plugin_spec.yaml", "spec.yaml", "plugin.yaml",
    ]
    spec_path = None
    for filename in spec_filenames:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            f"Tried: {', '.join(spec_filenames)}"
        )

    # Load the spec
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.lower().endswith(".json"):
            spec = json.load(f)
        elif yaml and (spec_path.lower().endswith(".yaml") or spec_path.lower().endswith(".yml")):
            spec = yaml.safe_load(f)
        else:
            raise ValueError("Unsupported plugin spec format")

    # Recursive flattening
    def _flatten(obj, parent_key=""):
        items = {}
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_key = f"{parent_key}.{key}" if parent_key else key
                items.update(_flatten(value, new_key))
        elif isinstance(obj, list):
            for idx, value in enumerate(obj):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                items.update(_flatten(value, new_key))
        else:
            items[parent_key] = obj
        return items

    flat_spec = _flatten(spec)
    return flat_spec

