    def _load_yaml(path):
        # Import yaml lazily so the function can still run in environments
        # where PyYAML is not installed unless a yaml file is actually needed.
        import yaml

        with open(path, "r", encoding="utf-8") as f:
            return yaml.safe_load(f)

