    spec_filenames = [
        "plugin.yaml",
        "plugin.yml",
        "plugin.json",
        "spec.yaml",
        "spec.yml",
        "spec.json",
    ]

    spec_data = {}
    for name in spec_filenames:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            try:
                if name.lower().endswith((".yaml", ".yml")):
                    spec_data = _load_yaml(path)
                else:
                    spec_data = _load_json(path)
            except Exception:
