        flat = {}
        for k, v in d.items():
            full_key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                flat.update(_flatten(v, full_key))
            else:
                flat[full_key] = v
        return flat

    return _flatten(spec_data)

