def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("root cannot be empty")
    if not path:
        raise ValueError("path cannot be empty")

    # Normalize root to remove trailing separators
    sep = "/" if "/" in root else "\\"
    normalized_root = root.rstrip(sep)

    if not path.startswith(normalized_root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")

    remainder = path[len(normalized_root):]
    # Remove leading separator if present
    if remainder.startswith(("/", "\\")):
        remainder = remainder[1:]

    return remainder

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, (str, bytes)) or not isinstance(root, (str, bytes)):
        raise TypeError("Both path and root must be strings")
    # Ensure we operate on strings, not bytes
    if isinstance(path, bytes):
        path = path.decode()
    if isinstance(root, bytes):
        root = root.decode()
    # Normalize root to end with a separator for matching
    sep = "/"
    root_clean = root.rstrip(sep) + sep
    # If the path is exactly the root without a trailing separator, return an empty string
    if path.rstrip(sep) == root.rstrip(sep):
        return ""
    # Check if the path starts with the cleaned root
    if path.startswith(root_clean):
        return path[len(root_clean):]
    # If it does not start with root, raise an error
    raise ValueError(f"Unable to strip root '{root}' from path '{path}'.")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Normalise by removing duplicate slashes and trailing slash (except root '/')
    def _norm(p):
        # collapse multiple slashes
        while '//' in p:
            p = p.replace('//', '/')
        # strip trailing slash unless it is the root "/"
        if len(p) > 1 and p.endswith('/'):
            p = p[:-1]
        return p

    root_norm = _norm(root)
    path_norm = _norm(path)

    # If both are identical, nothing to strip
    if path_norm == root_norm:
        return ""

    # Special handling when root is root "/"
    if root_norm == '/':
        if path_norm.startswith('/'):
            return path_norm[1:]
        else:
            raise ValueError(f"Root '/' is not a prefix of path '{path}'")

    # Ensure path starts with root + '/'
    prefix = root_norm + '/'
    if not path_norm.startswith(prefix):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    # Strip the root
    return path_norm[len(prefix):]
